import heapq


def build_order(tasks, priority):
    indeg = {t: 0 for t in tasks}
    dependents = {t: [] for t in tasks}
    for t, deps in tasks.items():
        if len(set(deps)) != len(deps):
            return None
        for d in deps:
            if d not in indeg or d == t:
                return None
            indeg[t] += 1
            dependents[d].append(t)
    heap = [(-priority.get(t, 0), t) for t in indeg if indeg[t] == 0]
    heapq.heapify(heap)
    out = []
    while heap:
        _, t = heapq.heappop(heap)
        out.append(t)
        for nxt in dependents[t]:
            indeg[nxt] -= 1
            if indeg[nxt] == 0:
                heapq.heappush(heap, (-priority.get(nxt, 0), nxt))
    return out if len(out) == len(tasks) else None
```

