def simulate_retries(outcomes, base_delay, cap, budget):
    attempts = 0
    total = 0
    for i, ok in enumerate(outcomes):
        if i > 0:
            delay = min(cap, base_delay * (2 ** i))
            if delay > budget - total:
                return [attempts, total]
            total += delay
        attempts += 1
        if ok:
            return [attempts, total]
    return [attempts, total]
