def justify_text(words, width):
    if width <= 0:
        raise ValueError("width must be positive")
    if not words:
        return []
    lines, cur, curlen = [], [], 0
    for w in words:
        if cur and curlen + 1 + len(w) > width:
            lines.append(cur)
            cur, curlen = [], 0
        if cur:
            curlen += 1
        cur.append(w)
        curlen += len(w)
    lines.append(cur)
    out = []
    for i, line in enumerate(lines):
        if i == len(lines) - 1 or len(line) == 1:
            out.append(" ".join(line))
            continue
        gaps = len(line) - 1
        spaces = width - sum(len(w) for w in line)
        base, extra = divmod(spaces, gaps)
        s = line[0]
        for j in range(gaps):
            s += " " * (base + (1 if j < extra else 0)) + line[j + 1]
        out.append(s)
    return out
```

