def autocomplete(entries, prefix, k):
    if k <= 0:
        return []
    totals = {}
    for word, weight in entries:
        totals[word] = totals.get(word, 0) + weight
    cands = [(w, wt) for w, wt in totals.items() if w.startswith(prefix)]
    cands.sort(key=lambda p: (-p[1], p[0]))
    return [w for w, _ in cands[:k]]
