def best_window(revenue, cost, k):
    n = len(revenue)
    if k <= 0 or k > n or len(cost) != n:
        return [-1, 0]
    cur = sum(revenue[:k]) - sum(cost[:k])
    best, best_i = cur, 0
    for i in range(k, n):
        cur += revenue[i] - cost[i] - revenue[i - k] + cost[i - k]
        if cur > best:
            best, best_i = cur, i - k + 1
    return [best_i, best]
```

