def token_bucket(events, rate, burst):
    tokens = float(burst)
    last = None
    out = []
    for ts, cost in events:
        if last is not None:
            if ts < last:
                raise ValueError("timestamps must be non-decreasing")
            tokens = min(float(burst), tokens + rate * (ts - last) / 1000.0)
        last = ts
        if cost <= burst and cost <= tokens + 1e-9:
            tokens -= cost
            out.append(True)
        else:
            out.append(False)
    return out
