import string


def decode_escapes(s):
    hexdigits = set(string.hexdigits)
    simple = {"n": "\n", "t": "\t", "r": "\r", "\\": "\\", '"': '"'}
    out = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c != "\\":
            out.append(c)
            i += 1
            continue
        if i + 1 >= n:
            raise ValueError("trailing backslash")
        e = s[i + 1]
        if e in simple:
            out.append(simple[e])
            i += 2
        elif e == "x":
            h = s[i + 2:i + 4]
            if len(h) != 2 or any(ch not in hexdigits for ch in h):
                raise ValueError("bad hex escape")
            out.append(chr(int(h, 16)))
            i += 4
        elif e == "u":
            h = s[i + 2:i + 6]
            if len(h) != 4 or any(ch not in hexdigits for ch in h):
                raise ValueError("bad unicode escape")
            out.append(chr(int(h, 16)))
            i += 6
        else:
            out.append("\\")
            out.append(e)
            i += 2
    return "".join(out)
```

