def dep_layers(graph):
    indeg = {p: 0 for p in graph}
    dependents = {p: [] for p in graph}
    for p, deps in graph.items():
        if len(set(deps)) != len(deps):
            return None
        for d in deps:
            if d not in graph:
                return None
            indeg[p] += 1
            dependents[d].append(p)
    placed = set()
    layers = []
    remaining = set(graph)
    while remaining:
        ready = sorted(p for p in remaining if all(d in placed for d in graph[p]))
        if not ready:
            return None
        layers.append(ready)
        placed.update(ready)
        remaining.difference_update(ready)
    return layers
```

