def effective_permissions(role_grants, user_roles):
    seen_roles = set()
    perms = set()

    def visit(role, stack):
        if role in stack:
            raise ValueError("cyclic role inheritance")
        if role in seen_roles or role not in role_grants:
            return
        seen_roles.add(role)
        for grant in role_grants[role]:
            if grant.startswith("@"):
                visit(grant[1:], stack | {role})
            else:
                perms.add(grant)

    for r in user_roles:
        visit(r, frozenset())
    if "*" in perms:
        return ["*"]
    return sorted(perms)
```

