function applyEdits(text, edits) {
  const sorted = edits.map((e, i) => ({ start: e.start, end: e.end, replacement: e.replacement, i }))
    .sort((a, b) => a.start - b.start || a.end - b.end);
  let prevEnd = 0;
  for (const e of sorted) {
    if (!Number.isInteger(e.start) || !Number.isInteger(e.end) || e.start < prevEnd || e.end < e.start || e.end > text.length) {
      throw new Error('invalid edit');
    }
    prevEnd = e.end;
  }
  let out = '';
  let pos = 0;
  for (const e of sorted) {
    out += text.slice(pos, e.start) + e.replacement;
    pos = e.end;
  }
  return out + text.slice(pos);
}
