function coalesceEvents(times, windowMs) {
  const bursts = [];
  for (let i = 0; i < times.length; i++) {
    if (i > 0 && times[i] < times[i - 1]) throw new Error('unsorted timestamps');
    if (i === 0 || times[i] - times[i - 1] > windowMs) {
      bursts.push([i]);
    } else {
      bursts[bursts.length - 1].push(i);
    }
  }
  return bursts;
}
