function sortRecords(records, keys) {
  return records
    .map((rec, idx) => ({ rec, idx }))
    .sort((A, B) => {
      for (const { key, dir } of keys) {
        const a = A.rec[key];
        const b = B.rec[key];
        const aMissing = a === undefined || a === null;
        const bMissing = b === undefined || b === null;
        if (aMissing || bMissing) {
          if (aMissing && bMissing) continue;
          return aMissing ? 1 : -1;
        }
        if (a < b) return dir === 1 ? -1 : 1;
        if (a > b) return dir === 1 ? 1 : -1;
      }
      return A.idx - B.idx;
    })
    .map(x => x.rec);
}
