function groupRuns(nums) {
  const out = [];
  for (let i = 0; i < nums.length; i++) {
    if (i > 0 && nums[i] < nums[i - 1]) throw new Error('decreasing sequence');
    const last = out[out.length - 1];
    if (last && nums[i] <= last[1]) continue;
    if (last && nums[i] === last[1] + 1) last[1] = nums[i];
    else out.push([nums[i], nums[i]]);
