function formatDuration(seconds: number, style: 'short' | 'clock'): string {
  if (!Number.isInteger(seconds) || seconds < 0) throw new Error('invalid duration');
  if (style !== 'short' && style !== 'clock') throw new Error('invalid duration');
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (style === 'clock') {
    return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }
  const parts: string[] = [];
  if (h > 0) parts.push(h + 'h');
  if (m > 0) parts.push(m + 'm');
  if (s > 0 || parts.length === 0) parts.push(s + 's');
  return parts.join(' ');
}
