function binarySearchRange(values: number[], target: number): [number, number] {
  let lo = 0;
  let hi = values.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (values[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  const first = lo;
  lo = 0;
  hi = values.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (values[mid] <= target) lo = mid + 1;
    else hi = mid;
  }
  if (first >= values.length || values[first] !== target) return [-1, -1];
  return [first, lo - 1];
}
