function matchGlob(pattern: string, name: string): boolean {
  const dp: boolean[][] = [];
  for (let i = 0; i <= pattern.length; i++) dp.push(new Array<boolean>(name.length + 1).fill(false));
  dp[0][0] = true;
  for (let i = 1; i <= pattern.length; i++) {
    if (pattern[i - 1] === '*') dp[i][0] = dp[i - 1][0];
  }
  for (let i = 1; i <= pattern.length; i++) {
    const p = pattern[i - 1];
    for (let j = 1; j <= name.length; j++) {
      if (p === '*') dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
      else if (p === '?' || p === name[j - 1]) dp[i][j] = dp[i - 1][j - 1];
    }
  }
  return dp[pattern.length][name.length];
}
