function unionLength(intervals: [number, number][]): number {
  const sorted = intervals.filter(([a, b]) => b > a).sort((x, y) => x[0] - y[0] || x[1] - y[1]);
  let total = 0;
  let curStart = 0;
  let curEnd = 0;
  let started = false;
  for (const [s, e] of sorted) {
    if (!started) {
      curStart = s;
      curEnd = e;
      started = true;
    } else if (s > curEnd) {
      total += curEnd - curStart;
      curStart = s;
      curEnd = e;
    } else if (e > curEnd) {
      curEnd = e;
    }
  }
  if (started) total += curEnd - curStart;
  return total;
}
