interface ParsedFlags {
  values: Record<string, string | boolean>;
  positional: string[];
}

function parseFlags(args: string[], spec: Record<string, 'bool' | 'string'>): ParsedFlags {
  const values: Record<string, string | boolean> = {};
  const positional: string[] = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--') {
      for (let k = i + 1; k < args.length; k++) positional.push(args[k]);
      break;
    }
    if (!arg.startsWith('--')) {
      positional.push(arg);
      continue;
    }
    const body = arg.slice(2);
    const eq = body.indexOf('=');
    let name = eq < 0 ? body : body.slice(0, eq);
    let value: string | undefined = eq < 0 ? undefined : body.slice(eq + 1);
    let negated = false;
    if (!(name in spec) && name.startsWith('no-') && spec[name.slice(3)] === 'bool') {
      name = name.slice(3);
      negated = true;
    }
    const kind = spec[name];
    if (kind === undefined) throw new Error('unknown flag: ' + name);
    if (kind === 'bool') {
      if (value !== undefined) throw new Error('flag takes no value: ' + name);
      values[name] = !negated;
      continue;
    }
    if (negated) throw new Error('unknown flag: ' + name);
    if (value === undefined) {
      if (i + 1 >= args.length) throw new Error('missing value: ' + name);
      value = args[++i];
    }
    values[name] = value;
  }
  return { values, positional };
}
