std::vector<std::string> uniquePrefixes(const std::vector<std::string>& words) {
    std::vector<std::string> out;
    out.reserve(words.size());
    for (size_t i = 0; i < words.size(); i++) {
        const std::string& w = words[i];
        size_t len = 1;
        while (len < w.size()) {
            bool clash = false;
            for (size_t j = 0; j < words.size() && !clash; j++) {
                if (j == i) continue;
                const std::string& o = words[j];
                if (o.size() >= len && o.compare(0, len, w, 0, len) == 0) clash = true;
            }
            if (!clash) break;
            len++;
        }
        out.push_back(w.substr(0, std::min(len, w.size())));
    }
    return out;
}
