long long maxCircular(const std::vector<long long>& values) {
    int n = (int)values.size();
    if (n == 0) return 0;
    long long best = values[0], cur = values[0];
    for (int i = 1; i < n; i++) {
        cur = std::max(values[i], cur + values[i]);
        best = std::max(best, cur);
    }
    if (best < 0) return best;
    long long total = 0;
    for (long long v : values) total += v;
    long long minEnd = values[0], minSum = values[0];
    for (int i = 1; i < n; i++) {
        minEnd = std::min(values[i], minEnd + values[i]);
        minSum = std::min(minSum, minEnd);
    }
    return std::max(best, total - minSum);
}
