static int parseStrictInt(const std::string& tok) {
    size_t pos = 0;
    int value = std::stoi(tok, &pos);
    if (pos != tok.size()) throw std::invalid_argument("bad number: " + tok);
    return value;
}

std::vector<int> expandRanges(const std::string& spec) {
    std::vector<int> out;
    if (spec.empty()) return out;
    size_t pos = 0;
    while (pos <= spec.size()) {
        size_t comma = spec.find(',', pos);
        std::string tok = spec.substr(pos, comma == std::string::npos ? std::string::npos : comma - pos);
        if (tok.empty()) throw std::invalid_argument("empty token");
        size_t dash = tok.find('-', 1);
        if (dash == std::string::npos) {
            out.push_back(parseStrictInt(tok));
        } else {
            int a = parseStrictInt(tok.substr(0, dash));
            int b = parseStrictInt(tok.substr(dash + 1));
            if (a > b) throw std::invalid_argument("descending range");
            for (int i = a; i <= b; i++) out.push_back(i);
        }
        if (comma == std::string::npos) break;
        pos = comma + 1;
    }
    return out;
}
