std::vector<int> slidingMax(const std::vector<int>& values, int k) {
    std::vector<int> out;
    int n = (int)values.size();
    if (k <= 0 || k > n) return out;
    std::deque<int> dq;
    for (int i = 0; i < n; i++) {
        while (!dq.empty() && dq.front() <= i - k) dq.pop_front();
        while (!dq.empty() && values[dq.back()] <= values[i]) dq.pop_back();
        dq.push_back(i);
        if (i >= k - 1) out.push_back(values[dq.front()]);
    }
    return out;
}
