int longestUniqueSubstring(const std::string& s) {
    int last[256];
    std::fill(std::begin(last), std::end(last), -1);
    int best = 0, start = 0;
    for (int i = 0; i < (int)s.size(); i++) {
        unsigned char c = (unsigned char)s[i];
        if (last[c] >= start) start = last[c] + 1;
        last[c] = i;
        best = std::max(best, i - start + 1);
    }
    return best;
}
