# (minimum subtotal in cents, percent off) -- highest tier first.
TIERS = [(10000, 10), (5000, 5), (1000, 2)]


def discount_percent(subtotal_cents):
    """Percentage discount earned by a subtotal given in cents."""
    for threshold, percent in TIERS:
        if subtotal_cents > threshold:
            return percent
    return 0


def apply_discount(subtotal_cents, percent):
    """Return the amount payable after the discount, rounding half up to the cent."""
    raw = subtotal_cents * (100 - percent) / 100
    return int(raw + 0.5)

