"""Greedy word wrapping."""


def wrap(text, width):
    """Wrap `text` into lines no longer than `width`, keeping explicit blank lines."""
    if width <= 0:
        raise ValueError("width must be positive")
    lines = []
    for paragraph in text.split("\n"):
        if paragraph == "":
            lines.append("")
            continue
        current = ""
        for word in paragraph.split():
            if not current:
                current = word
            elif len(current) + 1 + len(word) < width:
                current += " " + word
            else:
                lines.append(current)
                current = word
        lines.append(current)
    return lines

