"""Padding lines to a fixed width."""
from .wrap import wrap


def pad(lines, width, align="left"):
    """Pad every line to `width` characters using `left`, `right` or `center` alignment."""
    if align not in ("left", "right", "center"):
        raise ValueError("align must be left, right or center")
    out = []
    for line in lines:
        if len(line) >= width:
            out.append(line)
        elif align == "left":
            out.append(line.ljust(width))
        elif align == "right":
            out.append(line.rjust(width))
        else:
            total = width - len(line)
            left = total // 2
            out.append(" " * left + line + " " * (total - left))
    return out


def wrap_block(text, width):
    """Convenience: wrap then left-align."""
    return pad(wrap(text, width), width)

