from decimal import Decimal


def to_cents(amount):
    """Convert a decimal string/number to integer cents, rejecting more than two decimals."""
    d = Decimal(str(amount))
    if d.as_tuple().exponent < -2:
        raise ValueError("more than two decimals: %r" % (amount,))
    return int(d * 100)


def format_money(cents):
    """Render integer cents as `$12.05` (negative amounts get a leading minus)."""
    sign = "-" if cents < 0 else ""
    cents = abs(int(cents))
    return "%s$%d.%02d" % (sign, cents // 100, cents % 100)

