from .match import match

_SAFE = frozenset("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.~")


def _escape(text):
    """Percent-encode UTF-8 bytes outside the unreserved set."""
    out = []
    for ch in str(text):
        if ch in _SAFE:
            out.append(ch)
        else:
            for byte in ch.encode("utf-8"):
                out.append("%%%02X" % byte)
    return "".join(out)


def build_url(pattern, params):
    """Fill `:name` placeholders with URL-escaped values from `params`."""
    out = []
    for part in pattern.split("/"):
        if part.startswith(":") and part[1:]:
            if part[1:] not in params:
                raise KeyError(part[1:])
            out.append(_escape(params[part[1:]]))
        else:
            out.append(part)
    joined = "/".join(out)
    return joined if joined.startswith("/") else "/" + joined

