def max_gold_path(grid):
    if not grid or not grid[0]:
        return -1
    cols = len(grid[0])
    if any(len(row) != cols for row in grid):
        return -1
    if grid[0][0] == -1:
        return -1
    rows = len(grid)
    dp = [[-1] * cols for _ in range(rows)]
