        return 0
    ordered = sorted(jobs, key=lambda p: (-p[0], p[1]))
    last = max(d for _, d in jobs)
    parent = list(range(last + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

