function allocateBudget(requests, budget) {
  const total = requests.reduce((sum, r) => sum + Math.max(0, r.weight), 0);
  const result = requests.map(r => ({ name: r.name, amount: 0 }));
  if (total === 0 || budget <= 0) return result;
  let assigned = 0;
  const remainders = [];
  requests.forEach((r, index) => {
    const exact = budget * Math.max(0, r.weight);
    const share = Math.floor(exact / total);
    result[index].amount = share;
    assigned += share;
    remainders.push({ index, rem: exact % total });
  });
  let left = budget - assigned;
  remainders.sort((a, b) => b.rem - a.rem || a.index - b.index);
  for (let i = 0; i < remainders.length && left > 0; i++) {
    if (remainders[i].rem === 0) continue;
    result[remainders[i].index].amount += 1;
    left -= 1;
  }
  return result;
}
