function rotateMatrix(matrix, turns) {
  let current = matrix.map(row => row.slice());
  let times = ((turns % 4) + 4) % 4;
  for (let t = 0; t < times; t++) {
    const rows = current.length;
    const cols = rows ? current[0].length : 0;
    if (rows === 0 || cols === 0) return [];
    const next = [];
    for (let c = 0; c < cols; c++) {
      const row = [];
      for (let r = rows - 1; r >= 0; r--) row.push(current[r][c]);
      next.push(row);
    }
    current = next;
  }
  return current;
}
