function rollingMedian(values, k) {
  const n = values.length;
  if (k <= 0 || k > n) return [];
  const out = [];
  for (let start = 0; start + k <= n; start++) {
    const window = values.slice(start, start + k).sort((a, b) => a - b);
    if (k % 2 === 1) out.push(window[(k - 1) / 2]);
    else out.push((window[k / 2 - 1] + window[k / 2]) / 2);
  }
  return out;
}
