function wordBreak(text, dictionary) {
  const words = Array.from(new Set(dictionary)).filter(w => w.length > 0);
  const n = text.length;
  const best = new Array(n + 1).fill(null);
  best[0] = '';
  for (let end = 1; end <= n; end++) {
    let chosen = null;
    for (const word of words) {
      const start = end - word.length;
      if (start < 0 || best[start] === null) continue;
      if (text.slice(start, end) !== word) continue;
      const candidate = best[start] === '' ? word : best[start] + ' ' + word;
      if (chosen === null || candidate < chosen) chosen = candidate;
    }
    best[end] = chosen;
  }
  return best[n];
}
