function mergeStreams(streams) {
  const positions = streams.map(() => 0);
  const out = [];
  while (true) {
    let best = -1;
    for (let i = 0; i < streams.length; i++) {
      if (positions[i] >= streams[i].length) continue;
      if (best === -1 || streams[i][positions[i]] < streams[best][positions[best]]) best = i;
    }
    if (best === -1) break;
    out.push(streams[best][positions[best]]);
    positions[best] += 1;
  }
  return out;
}
