function countBitsRange(n) {
  if (!(n >= 0)) return 0;
  let count = 0;
  for (let bit = 0; bit < 53; bit++) {
    const half = Math.pow(2, bit);
    const cycle = half * 2;
    const total = n + 1;
    const fullCycles = Math.floor(total / cycle);
    const remainder = Math.max(0, (total % cycle) - half);
    count += fullCycles * half + remainder;
  }
  return count;
}
