function parseCronField(field: string, min: number, max: number): number[] {
  if (field.trim() === '') throw new RangeError('empty field');
  const values = new Set<number>();
  for (const part of field.split(',')) {
    if (part === '') throw new RangeError('empty part');
    const pieces = part.split('/');
    if (pieces.length > 2) throw new RangeError('bad step');
    const body = pieces[0];
    let step = 1;
    if (pieces.length === 2) {
      if (!/^\d+$/.test(pieces[1])) throw new RangeError('bad step');
      step = Number(pieces[1]);
      if (step <= 0) throw new RangeError('bad step');
    }
    let lo: number;
    let hi: number;
    if (body === '*') {
      lo = min;
      hi = max;
    } else if (body.includes('-')) {
      const bounds = body.split('-');
      if (bounds.length !== 2 || !/^\d+$/.test(bounds[0]) || !/^\d+$/.test(bounds[1])) throw new RangeError('bad range');
      lo = Number(bounds[0]);
      hi = Number(bounds[1]);
    } else {
      if (!/^\d+$/.test(body)) throw new RangeError('bad value');
      lo = Number(body);
      hi = pieces.length === 2 ? max : lo;
    }
    if (lo < min || hi > max || lo > hi) throw new RangeError('out of range');
    for (let v = lo; v <= hi; v += step) values.add(v);
  }
  return Array.from(values).sort((a, b) => a - b);
}
```

