function chunkDates(startISO: string, endISO: string, days: number): [string, string][] {
  if (!Number.isInteger(days) || days <= 0) throw new RangeError('days must be a positive integer');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(startISO) || !/^\d{4}-\d{2}-\d{2}$/.test(endISO)) {
    throw new RangeError('bad date');
  }
  const start = Date.parse(startISO + 'T00:00:00Z');
  const end = Date.parse(endISO + 'T00:00:00Z');
  if (!Number.isFinite(start) || !Number.isFinite(end)) throw new RangeError('bad date');
  if (start > end) throw new RangeError('start after end');
  const day = 86400000;
  const step = days * day;
  const out: [string, string][] = [];
  for (let cursor = start; cursor <= end; cursor += step) {
    const last = Math.min(end, cursor + step - day);
    out.push([new Date(cursor).toISOString().slice(0, 10), new Date(last).toISOString().slice(0, 10)]);
  }
  return out;
}
