interface Stats {
  count: number;
  min: number;
  max: number;
  sum: number;
  mean: number;
  median: number;
  mode: number;
}

function stats(values: number[]): Stats | null {
  if (values.length === 0) return null;
  const sorted = values.slice().sort((a, b) => a - b);
  const count = sorted.length;
  const sum = sorted.reduce((acc, v) => acc + v, 0);
  const middle = Math.floor(count / 2);
  const median = count % 2 === 1 ? sorted[middle] : (sorted[middle - 1] + sorted[middle]) / 2;
  const freq = new Map<number, number>();
  for (const v of sorted) freq.set(v, (freq.get(v) ?? 0) + 1);
  let mode = sorted[0];
  let best = 0;
  for (const [value, n] of freq) {
    if (n > best || (n === best && value < mode)) {
      mode = value;
      best = n;
    }
  }
  return { count, min: sorted[0], max: sorted[count - 1], sum, mean: sum / count, median, mode };
}
