function matrixMultiply(a: number[][], b: number[][]): number[][] {
  const rows = a.length;
  const inner = rows > 0 ? a[0].length : 0;
  const cols = b.length > 0 ? b[0].length : 0;
  if (rows === 0 || inner === 0 || cols === 0) throw new Error('dimension mismatch');
  for (const row of a) if (row.length !== inner) throw new Error('dimension mismatch');
  for (const row of b) if (row.length !== cols) throw new Error('dimension mismatch');
  if (b.length !== inner) throw new Error('dimension mismatch');
  const out: number[][] = [];
  for (let i = 0; i < rows; i++) {
    const row: number[] = [];
    for (let j = 0; j < cols; j++) {
      let acc = 0;
      for (let k = 0; k < inner; k++) acc += a[i][k] * b[k][j];
      row.push(acc);
    }
    out.push(row);
  }
  return out;
}
