int distinctSubstrings(const std::string& s, int k) {
    if (k <= 0 || (size_t)k > s.size()) return 0;
    const unsigned long long base = 1315423911ULL;
    unsigned long long power = 1;
    for (int i = 1; i < k; i++) power *= base;
    unsigned long long hash = 0;
    for (int i = 0; i < k; i++) hash = hash * base + (unsigned char)s[i];
    std::unordered_set<unsigned long long> seen;
    seen.insert(hash);
    for (size_t i = k; i < s.size(); i++) {
        hash = (hash - (unsigned char)s[i - k] * power) * base + (unsigned char)s[i];
        seen.insert(hash);
    }
    return (int)seen.size();
}
