bool canPartition(const std::vector<int>& values) {
    long long total = 0;
    for (int v : values) total += v;
    if (values.empty() || total % 2 != 0) return false;
    int target = (int)(total / 2);
    std::vector<char> reach(target + 1, 0);
    reach[0] = 1;
    for (int v : values) {
        if (v > target) continue;
        for (int s = target; s >= v; s--) {
            if (reach[s - v]) reach[s] = 1;
        }
    }
    return reach[target] != 0;
}
