double medianOfTwoSorted(const std::vector<int>& a, const std::vector<int>& b) {
    const std::vector<int>& small = a.size() <= b.size() ? a : b;
    const std::vector<int>& large = a.size() <= b.size() ? b : a;
    int m = (int)small.size();
    int n = (int)large.size();
    int lo = 0, hi = m;
    while (lo <= hi) {
        int cutSmall = (lo + hi) / 2;
        int cutLarge = (m + n + 1) / 2 - cutSmall;
        int leftSmall = cutSmall == 0 ? INT32_MIN : small[cutSmall - 1];
        int rightSmall = cutSmall == m ? INT32_MAX : small[cutSmall];
        int leftLarge = cutLarge == 0 ? INT32_MIN : large[cutLarge - 1];
        int rightLarge = cutLarge == n ? INT32_MAX : large[cutLarge];
        if (leftSmall <= rightLarge && leftLarge <= rightSmall) {
            if ((m + n) % 2 == 1) return std::max(leftSmall, leftLarge);
            return (std::max(leftSmall, leftLarge) + std::min(rightSmall, rightLarge)) / 2.0;
        }
        if (leftSmall > rightLarge) hi = cutSmall - 1;
        else lo = cutSmall + 1;
    }
    return 0.0;
}
