"""Keyset pagination over an in-memory list."""


def page(items, limit, cursor=None):
    """Return (rows, next_cursor) for one page of `items`.

    `cursor` is the id of the last row of the previous page (None for the first page).
    `next_cursor` is None when there are no further rows.
    """
    if limit <= 0:
        raise ValueError("limit must be positive")
    start = 0
    if cursor is not None:
        for index, item in enumerate(items):
            if item["id"] == cursor:
                start = index
                break
        else:
            return [], None
    rows = items[start:start + limit]
    if not rows:
        return [], None
    more = start + limit < len(items)
    return rows, (rows[-1]["id"] if more else None)

