def encode_base62(n):
    if n < 0:
        raise ValueError("negative value")
    if n == 0:
        return "0"
    digits = []
    while n:
        digits.append(ALPHABET[n % 62])
        n //= 62
    return "".join(reversed(digits))


def decode_base62(s):
    if not s:
        raise ValueError("empty string")
    value = 0
    for ch in s:
        index = ALPHABET.find(ch)
        if index < 0:
            raise ValueError("invalid character: %r" % ch)
        value = value * 62 + index
    return value
