from collections import deque


def word_ladder(begin, end, words):
    if begin == end:
        return 1
    pool = set(words)
    if end not in pool:
        return 0
    queue = deque([(begin, 1)])
    seen = {begin}
    while queue:
        word, depth = queue.popleft()
        for i in range(len(word)):
            for code in range(97, 123):
                candidate = word[:i] + chr(code) + word[i + 1:]
                if candidate == end:
                    return depth + 1
                if candidate in pool and candidate not in seen:
                    seen.add(candidate)
                    queue.append((candidate, depth + 1))
    return 0
