std::string applyEdits(const std::string& text, const std::vector<std::tuple<int, int, std::string>>& edits) {
    std::vector<std::tuple<int, int, std::string>> ordered = edits;
    std::sort(ordered.begin(), ordered.end(), [](const auto& a, const auto& b) {
        if (std::get<0>(a) != std::get<0>(b)) return std::get<0>(a) < std::get<0>(b);
        return std::get<1>(a) < std::get<1>(b);
    });
    int previous_end = 0;
    for (const auto& edit : ordered) {
        int start = std::get<0>(edit);
        int end = std::get<1>(edit);
        if (start < 0 || end < start || end > (int)text.size() || start < previous_end) {
            throw std::invalid_argument("invalid edit");
        }
        previous_end = end;
    }
    std::string out;
    int cursor = 0;
    for (const auto& edit : ordered) {
        int start = std::get<0>(edit);
        int end = std::get<1>(edit);
        out.append(text, cursor, start - cursor);
        out += std::get<2>(edit);
        cursor = end;
    }
    out.append(text, cursor, text.size() - cursor);
    return out;
}
