int minCoinsBounded(const std::vector<int>& coins, const std::vector<int>& counts, int amount) {
    if (amount < 0) return -1;
    const int INF = 1e9;
    std::vector<int> dp(amount + 1, INF);
    dp[0] = 0;
    for (size_t i = 0; i < coins.size() && i < counts.size(); i++) {
        int value = coins[i];
        int count = counts[i];
        if (value <= 0 || count <= 0) continue;
        int chunk = 1;
        while (count > 0) {
            int take = std::min(chunk, count);
            int weight = value * take;
            int cost = take;
            for (int cap = amount; cap >= weight; cap--) {
                if (dp[cap - weight] + cost < dp[cap]) dp[cap] = dp[cap - weight] + cost;
            }
            count -= take;
            chunk *= 2;
        }
    }
    return dp[amount] >= INF ? -1 : dp[amount];
}
```

