int lcsLength(const std::string& a, const std::string& b) {
    if (a.size() < b.size()) return lcsLength(b, a);
    int m = (int)b.size();
    std::vector<int> previous(m + 1, 0), current(m + 1, 0);
    for (size_t i = 1; i <= a.size(); i++) {
        std::fill(current.begin(), current.end(), 0);
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1]) current[j] = previous[j - 1] + 1;
            else current[j] = std::max(previous[j], current[j - 1]);
        }
        previous.swap(current);
    }
    return previous[m];
}
