async function withRetry(task, attempts) {
  if (attempts <= 0) throw new Error('attempts must be at least 1');
  let lastError;
  for (let attempt = 0; attempt < attempts; attempt++) {
    try {
      return await task();
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError;
}
```

