function sanitizeFilename(name) {
  let out = String(name).replace(/[<>:"/\\|?*\x00-\x1f]/g, '-');
  out = out.replace(/-+/g, '-');
  out = out.replace(/^[.\s-]+|[.\s-]+$/g, '');
  out = out.slice(0, 64).replace(/^[.\s-]+|[.\s-]+$/g, '');
  return out === '' ? 'untitled' : out;
}
