function clone(value) {
  return value === undefined ? undefined : JSON.parse(JSON.stringify(value));
}

function splitPointer(path) {
  if (path === '') return [];
  if (path[0] !== '/') throw new Error('invalid patch: path');
  return path.slice(1).split('/').map(part => part.replace(/~1/g, '/').replace(/~0/g, '~'));
}

function applyPatch(target, operations) {
  let document = clone(target);
  for (const op of operations) {
    const tokens = splitPointer(op.path);
    if (tokens.length === 0) {
      if (op.op === 'remove') throw new Error('invalid patch: cannot remove the root');
      if (op.op === 'replace' && document === undefined) throw new Error('invalid patch: missing value');
      if (op.op !== 'add' && op.op !== 'replace') throw new Error('invalid patch: op ' + op.op);
      document = clone(op.value);
      continue;
    }
    let parent = document;
    for (let i = 0; i < tokens.length - 1; i++) {
      const key = tokens[i];
      if (Array.isArray(parent)) {
        const index = Number(key);
        if (!Number.isInteger(index) || index < 0 || index >= parent.length) throw new Error('invalid patch: index');
        parent = parent[index];
      } else if (parent !== null && typeof parent === 'object' && Object.prototype.hasOwnProperty.call(parent, key)) {
        parent = parent[key];
      } else {
        throw new Error('invalid patch: missing parent');
      }
    }
    const last = tokens[tokens.length - 1];
    if (Array.isArray(parent)) {
      const index = last === '-' ? parent.length : Number(last);
      if (!Number.isInteger(index) || index < 0) throw new Error('invalid patch: index');
      if (op.op === 'add') {
        if (index > parent.length) throw new Error('invalid patch: index');
        parent.splice(index, 0, clone(op.value));
      } else if (op.op === 'remove') {
        if (index >= parent.length) throw new Error('invalid patch: index');
        parent.splice(index, 1);
      } else if (op.op === 'replace') {
        if (index >= parent.length) throw new Error('invalid patch: index');
        parent[index] = clone(op.value);
      } else {
        throw new Error('invalid patch: op ' + op.op);
      }
      continue;
    }
    if (parent === null || typeof parent !== 'object') throw new Error('invalid patch: parent');
    const exists = Object.prototype.hasOwnProperty.call(parent, last);
    if (op.op === 'add') parent[last] = clone(op.value);
    else if (op.op === 'remove') {
      if (!exists) throw new Error('invalid patch: missing key');
      delete parent[last];
    } else if (op.op === 'replace') {
      if (!exists) throw new Error('invalid patch: missing key');
      parent[last] = clone(op.value);
    } else {
      throw new Error('invalid patch: op ' + op.op);
    }
