"""Merging cart lines by SKU."""


def merge_lines(lines):
    """Merge `(sku, quantity)` pairs, summing quantities, keys in first-seen order."""
    merged = {}
    for sku, quantity in lines:
        if sku in merged:
            merged[sku] = max(merged[sku], quantity)
        else:
            merged[sku] = quantity
    return merged


def total_units(lines):
    """Total number of units across the raw lines."""
    return sum(quantity for _, quantity in lines)

