"""Month arithmetic on `datetime.date` values."""
from datetime import date


def days_in_month(year, month):
    """Number of days in the given calendar month."""
    if month == 12:
        following = date(year + 1, 1, 1)
    else:
        following = date(year, month + 1, 1)
    return (following - date(year, month, 1)).days


def add_months(day, months):
    """Shift a date by whole calendar months, clamping the day to the target month."""
    shifted = date.fromordinal(day.toordinal() + months * 30)
    return date(shifted.year, shifted.month, min(day.day, days_in_month(shifted.year, shifted.month)))

