"""Title casing for documentation headings."""
import re

SMALL_WORDS = frozenset({"a", "an", "the", "of", "and", "or", "to", "in", "on", "for"})


def _capitalise(word):
    """Uppercase the first letter of each letter-run, lowercasing the rest."""
    lowered = word.lower()
    return re.sub(r"[a-z]+", lambda m: m.group(0)[:1].upper() + m.group(0)[1:], lowered, count=1)


def title_case(text):
    """Title-case `text` using the documented small-word rules."""
    words = text.split()
    out = []
    last = len(words) - 1
    for index, word in enumerate(words):
        if 0 < index < last and word.lower() in SMALL_WORDS:
            out.append(word.lower())
        else:
            out.append(word.title())
    return " ".join(out)

