"""Encoding JSON string literals and scalars."""


def encode_string(text):
    """Return a JSON string literal (including the surrounding quotes)."""
    pieces = ['"']
    for ch in text:
        if ch == '"':
            pieces.append('\\"')
        elif ch == "\\":
            pieces.append("\\\\")
        elif ch in "\n\t\r":
            pieces.append(ch)
        elif ord(ch) < 0x20:
            pieces.append("\\u%04x" % ord(ch))
        else:
            pieces.append(ch)
    pieces.append('"')
    return "".join(pieces)


def encode_scalar(value):
    """Encode a string, boolean, integer or None as JSON."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (int, float)):
        return repr(value)
    return encode_string(str(value))

