"""Luhn (mod-10) checksum."""


def luhn_valid(number):
    """True when `number` (digits, spaces allowed) passes the Luhn checksum."""
    digits = [int(ch) for ch in number if ch != " "]
    if not digits:
        return False
    total = 0
    for index, digit in enumerate(reversed(digits)):
        if index % 2 == 0:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0

