def quantile(values, q):
    if not values:
        raise ValueError("empty values")
    if not 0.0 <= q <= 1.0:
        raise ValueError("q out of range")
    data = sorted(values)
    position = q * (len(data) - 1)
    lower = int(position)
    fraction = position - lower
    if fraction == 0:
        return float(data[lower])
    return data[lower] + fraction * (data[lower + 1] - data[lower])
