def bin_pack(capacity, items):
    if capacity <= 0:
        raise ValueError("capacity must be positive")
    for item in items:
        if item > capacity:
            raise ValueError("item does not fit")
    remaining = []
    for item in sorted(items, reverse=True):
        for index, room in enumerate(remaining):
            if room >= item:
                remaining[index] = room - item
                break
        else:
            remaining.append(capacity - item)
    return remaining
