def cycle_of(nxt):
    n = len(nxt)
    if n == 0:
        raise ValueError("empty mapping")
    for value in nxt:
        if not 0 <= value < n:
            raise ValueError("value out of range")
    seen = {}
    node = 0
    step = 0
    while node not in seen:
        seen[node] = step
        node = nxt[node]
        step += 1
    members = [value for value, order in seen.items() if order >= seen[node]]
    return min(members), len(members)
