def valid_utf8(data):
    index = 0
    total = len(data)
    while index < total:
        lead = data[index]
        if not 0 <= lead <= 0xFF:
            return False
        if lead <= 0x7F:
            index += 1
            continue
        if 0xC2 <= lead <= 0xDF:
            count = 1
        elif 0xE0 <= lead <= 0xEF:
            count = 2
        elif 0xF0 <= lead <= 0xF4:
            count = 3
        else:
            return False
        if index + count >= total:
            return False
        body = data[index + 1:index + 1 + count]
        for byte in body:
            if not 0x80 <= byte <= 0xBF:
                return False
        if lead == 0xE0 and body[0] < 0xA0:
            return False
        if lead == 0xED and body[0] > 0x9F:
            return False
        if lead == 0xF0 and body[0] < 0x90:
            return False
        if lead == 0xF4 and body[0] > 0x8F:
            return False
        index += count + 1
    return True
