ONES = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"]
TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]
SCALES = [(1000000000, "billion"), (1000000, "million"), (1000, "thousand"), (1, "")]


def _under_thousand(value):
    parts = []
    if value >= 100:
        parts.append(ONES[value // 100] + " hundred")
        value %= 100
    if value:
        if value < 20:
            parts.append(ONES[value])
        else:
            tens, units = divmod(value, 10)
            parts.append(TENS[tens] + ("-" + ONES[units] if units else ""))
    return " ".join(parts)


def number_to_words(n):
    if not 0 <= n <= 999999999:
        raise ValueError("out of range")
    if n == 0:
        return "zero"
    parts = []
    for size, name in SCALES:
        if n >= size:
            chunk = _under_thousand(n // size)
            parts.append(chunk + (" " + name if name else ""))
            n %= size
    return " ".join(parts)
