int maxProfitK(const std::vector<int>& prices, int k) {
    int n = static_cast<int>(prices.size());
    if (k <= 0 || n < 2) return 0;
    if (k >= n / 2) {
        int total = 0;
        for (int i = 1; i < n; i++) total += std::max(0, prices[i] - prices[i - 1]);
        return total;
    }
    const int NEG = std::numeric_limits<int>::min() / 4;
    std::vector<int> hold(k + 1, NEG), free(k + 1, 0);
    for (int price : prices) {
        for (int used = k; used >= 1; used--) {
            if (hold[used] > NEG && hold[used] + price > free[used]) free[used] = hold[used] + price;
            if (free[used - 1] - price > hold[used]) hold[used] = free[used - 1] - price;
        }
    }
    return free[k];
}
```

