long long countSubarraysWithSum(const std::vector<int>& values, long long target) {
    std::unordered_map<long long, long long> seen;
    seen[0] = 1;
    long long running = 0;
    long long total = 0;
    for (int value : values) {
        running += value;
        auto it = seen.find(running - target);
        if (it != seen.end()) total += it->second;
        seen[running] += 1;
    }
    return total;
}
