long long reverseBits(long long value) {
    unsigned int x = static_cast<unsigned int>(value & 0xFFFFFFFFLL);
    unsigned int result = 0;
    for (int i = 0; i < 32; i++) {
        result = (result << 1) | (x & 1u);
        x >>= 1;
    }
