bool wordPattern(const std::string& pattern, const std::string& sentence) {
    if (pattern.empty() || sentence.empty()) return pattern.empty() && sentence.empty();
    std::vector<std::string> words;
    std::string current;
    for (char c : sentence) {
        if (c == ' ') {
            if (!current.empty()) { words.push_back(current); current.clear(); }
        } else current += c;
    }
    if (!current.empty()) words.push_back(current);
    if (words.size() != pattern.size()) return false;
    std::map<char, std::string> forward;
    std::map<std::string, char> backward;
    for (size_t i = 0; i < words.size(); i++) {
        char key = pattern[i];
        auto f = forward.find(key);
        if (f == forward.end()) forward[key] = words[i];
        else if (f->second != words[i]) return false;
        auto b = backward.find(words[i]);
        if (b == backward.end()) backward[words[i]] = key;
        else if (b->second != key) return false;
    }
    return true;
}
```

