function compose(...fns) {
  return (...args) => {
    if (fns.length === 0) return args[0];
    let value = fns[fns.length - 1](...args);
    for (let i = fns.length - 2; i >= 0; i--) value = fns[i](value);
    return value;
  };
}

function pipe(...fns) {
  return (...args) => {
    if (fns.length === 0) return args[0];
    let value = fns[0](...args);
    for (let i = 1; i < fns.length; i++) value = fns[i](value);
    return value;
  };
}
