      if (inner === '' && i === brackets.length - 1) {
        append = true;
      } else {
        path.push(inner);
      }
    }
    let node = root;
    for (let i = 0; i < path.length; i++) {
      const key = path[i];
      const last = i === path.length - 1;
      if (last) {
        if (append) {
          if (!Array.isArray(node[key])) node[key] = [];
          node[key].push(value);
