function stripAnsi(text) {
  const ESC = String.fromCharCode(27);
  let out = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] !== ESC) {
      out += text[i];
      i += 1;
      continue;
    }
    if (text[i + 1] === '[') {
      let j = i + 2;
      while (j < text.length && !/[A-Za-z]/.test(text[j])) j += 1;
      i = j + 1;
      continue;
    }
    if (text[i + 1] === ']') {
      let j = i + 2;
      while (j < text.length && text[j] !== String.fromCharCode(7)) {
        if (text[j] === ESC && text[j + 1] === '\\') { j += 2; break; }
        j += 1;
      }
      if (text[j] === String.fromCharCode(7)) j += 1;
      i = j;
      continue;
    }
    i += 1;
  }
  return out;
}
