type Field<T> = { key: keyof T; desc?: boolean };

function sortByFields<T>(items: T[], fields: Field<T>[]): T[] {
  const indexed = items.map((value, index) => ({ value, index }));
  indexed.sort((left, right) => {
    for (const field of fields) {
      const a = left.value[field.key];
      const b = right.value[field.key];
      if (a < b) return field.desc ? 1 : -1;
      if (a > b) return field.desc ? -1 : 1;
    }
    return left.index - right.index;
  });
  return indexed.map(entry => entry.value);
}
