function minBy<T>(items: T[], pick: (item: T) => number): T | undefined {
  let best: T | undefined = undefined;
  let bestValue = Infinity;
  for (const item of items) {
    const value = pick(item);
    if (best === undefined || value < bestValue) {
      best = item;
      bestValue = value;
    }
  }
  return best;
}

