def make_bbox(lat1, lon1, lat2, lon2):
    """Normalised (min_lat, min_lon, max_lat, max_lon) box from two corners."""
    return (min(lat1, lat2), min(lon1, lon2), max(lat1, lat2), max(lon1, lon2))


def bbox_contains(box, lat, lon):
    """True when the point lies inside the box, edges included."""
