"""Opaque cursor tokens for offset pagination."""
import base64


def encode_cursor(offset):
    """Base64 (urlsafe, padded) of the decimal offset."""
    return base64.urlsafe_b64encode(str(offset).encode("ascii")).decode("ascii")


def decode_cursor(token):
    """Recover the offset from a token that may or may not carry padding."""
    return int(base64.urlsafe_b64decode(token.encode("ascii")).decode("ascii"))


def page_slice(items, cursor, size):
    """The page of `size` items starting at the decoded cursor (0 when absent)."""
    start = 0 if not cursor else decode_cursor(cursor)
    return items[start:start + size]

