import heapq


def merge_k(lists):
    heap = []
    for index, values in enumerate(lists):
        if values:
            heapq.heappush(heap, (values[0], index, 0))
    out = []
    while heap:
        value, list_index, position = heapq.heappop(heap)
        out.append(value)
        position += 1
        if position < len(lists[list_index]):
            heapq.heappush(heap, (lists[list_index][position], list_index, position))
    return out
