def pascal_row(n):
    if n < 0:
        raise ValueError("n must be non-negative")
    row = [1]
    for size in range(1, n + 1):
        row.append(1)
        for index in range(size - 1, 0, -1):
            row[index] = row[index] + row[index - 1]
    return row
