bool isPalindrome(const std::string& text) {
    auto keep = [](char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9');
    };
    auto lower = [](char c) {
        return (c >= 'A' && c <= 'Z') ? static_cast<char>(c - 'A' + 'a') : c;
    };
    size_t i = 0, j = text.size();
    while (true) {
        while (i < j && !keep(text[i])) i++;
