    if (pattern.empty() || text.empty()) return {};
    std::vector<int> failure(pattern.size(), 0);
    for (size_t i = 1; i < pattern.size(); i++) {
        int j = failure[i - 1];
        while (j > 0 && pattern[i] != pattern[j]) j = failure[j - 1];
        if (pattern[i] == pattern[j]) j++;
        failure[i] = j;
    }
    std::vector<int> out;
    int matched = 0;
    for (size_t i = 0; i < text.size(); i++) {
