int decodeWays(const std::string& digits) {
    int n = static_cast<int>(digits.size());
    if (n == 0) return 1;
    std::vector<int> dp(n + 1, 0);
    dp[0] = 1;
    dp[1] = digits[0] == '0' ? 0 : 1;
    for (int i = 2; i <= n; i++) {
        int one = digits[i - 1] - '0';
        int two = (digits[i - 2] - '0') * 10 + one;
        if (one >= 1 && one <= 9) dp[i] += dp[i - 1];
