function parseColor(text) {
  if (typeof text !== 'string') return null;
  const value = text.trim();
  const short = /^#([0-9a-fA-F]{3})$/.exec(value);
  if (short) {
    const digits = short[1].split('').map(ch => parseInt(ch + ch, 16));
    return { r: digits[0], g: digits[1], b: digits[2] };
  }
  const long = /^#([0-9a-fA-F]{6})$/.exec(value);
  if (long) {
    const hex = long[1];
    return {
      r: parseInt(hex.slice(0, 2), 16),
      g: parseInt(hex.slice(2, 4), 16),
      b: parseInt(hex.slice(4, 6), 16),
    };
  }
  const rgb = /^rgb\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*\)$/.exec(value);
  if (rgb) {
    const parts = [Number(rgb[1]), Number(rgb[2]), Number(rgb[3])];
    if (parts.some(part => part > 255)) return null;
    return { r: parts[0], g: parts[1], b: parts[2] };
  }
  return null;
}
