function splitTopLevel(text, separator) {
  if (typeof separator !== 'string' || separator.length !== 1) throw new RangeError('single character separator expected');
  const out = [];
  let depth = 0;
  let quoted = false;
  let current = '';
  for (const ch of text) {
    if (quoted) {
      current += ch;
      if (ch === "'") quoted = false;
      continue;
    }
    if (ch === "'") { quoted = true; current += ch; continue; }
    if (ch === '(' || ch === '[' || ch === '{') depth += 1;
    else if (ch === ')' || ch === ']' || ch === '}') depth = Math.max(0, depth - 1);
    if (ch === separator && depth === 0) { out.push(current); current = ''; continue; }
    current += ch;
  }
  out.push(current);
  return out;
}
