"""Keeping the newest attempt of every job id."""


def dedupe_latest(jobs):
    """`jobs` is a list of (job_id, seq, payload); keep the highest seq per id."""
    best = {}
    for job_id, seq, payload in jobs:
        current = best.get(job_id)
        if current is None:
            best[job_id] = (seq, payload)
    return {job_id: payload for job_id, (seq, payload) in best.items()}


def order_ids(jobs):
    """Ids in first-seen order, without duplicates."""
    seen = []
    for job_id, _, _ in jobs:
        if job_id not in seen:
            seen.append(job_id)
    return seen


def pending_count(jobs):
    """How many distinct ids are queued."""
    return len({job_id for job_id, _, _ in jobs})

