def life_step(board):
    if not board:
        return []
    width = len(board[0])
    if any(len(row) != width for row in board):
        raise ValueError("board must be rectangular")
    height = len(board)
    out = [[0] * width for _ in range(height)]
    for row in range(height):
        for col in range(width):
            live = 0
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    r, c = row + dr, col + dc
                    if 0 <= r < height and 0 <= c < width and board[r][c]:
                        live += 1
            if board[row][col]:
