def wildcard_match(text, pattern):
    i = j = 0
    star = -1
    restore = 0
    while i < len(text):
        if j < len(pattern) and (pattern[j] == "?" or pattern[j] == text[i]):
            i += 1
            j += 1
        elif j < len(pattern) and pattern[j] == "*":
            star = j
            restore = i
            j += 1
        elif star != -1:
            j = star + 1
            restore += 1
            i = restore
        else:
            return False
    while j < len(pattern) and pattern[j] == "*":
