```typescript
type TreeNode<T> = { value: T; children?: TreeNode<T>[] };
type FlatNode<T> = { value: T; depth: number; path: string };

function flattenTree<T>(nodes: TreeNode<T>[]): FlatNode<T>[] {
  const out: FlatNode<T>[] = [];
  const walk = (list: TreeNode<T>[], depth: number, prefix: string) => {
    list.forEach((node, index) => {
      const path = prefix === '' ? String(index) : prefix + '.' + index;
      out.push({ value: node.value, depth, path });
      if (node.children && node.children.length > 0) walk(node.children, depth + 1, path);
    });
  };
  walk(nodes, 0, '');
  return out;
}
```

