type Row = { id: string; parentId: string | null; value: number };
type Node = { id: string; value: number; children: Node[] };

function buildTree(rows: Row[]): Node[] {
  const nodes = new Map<string, Node>();
  for (const row of rows) {
    if (!nodes.has(row.id)) nodes.set(row.id, { id: row.id, value: row.value, children: [] });
  }
  const roots: Node[] = [];
  for (const row of rows) {
    const node = nodes.get(row.id);
    if (node === undefined) continue;
    const parent = row.parentId === null ? undefined : nodes.get(row.parentId);
    if (parent === undefined) roots.push(node);
    else parent.children.push(node);
  }
  return roots;
}
