```typescript
type Column<T> = { key: keyof T; header: string; align?: 'left' | 'right' };

function renderTable<T>(rows: T[], columns: Column<T>[]): string {
  const cells = rows.map(row => columns.map(column => String(row[column.key])));
  const widths = columns.map((column, index) =>
    Math.max(column.header.length, ...cells.map(row => row[index].length), 0),
  );
  const pad = (text: string, width: number, align?: 'left' | 'right') =>
    align === 'right' ? text.padStart(width, ' ') : text.padEnd(width, ' ');
  const header = columns.map((column, index) => pad(column.header, widths[index], column.align)).join(' | ');
  const separator = widths.map(width => '-'.repeat(width)).join('-+-');
  const body = cells.map(row => row.map((cell, index) => pad(cell, widths[index], columns[index].align)).join(' | '));
  return [header, separator, ...body].join('\n');
}
