function chunkWhile<T>(items: T[], same: (previous: T, current: T) => boolean): T[][] {
  const groups: T[][] = [];
  for (const item of items) {
    const last = groups[groups.length - 1];
    if (last !== undefined && same(last[last.length - 1], item)) last.push(item);
    else groups.push([item]);
  }
  return groups;
}
