std::vector<int> nextPermutation(std::vector<int> values) {
    if (values.size() < 2) return values;
    int index = static_cast<int>(values.size()) - 2;
    while (index >= 0 && values[index] >= values[index + 1]) index--;
    if (index < 0) {
        std::reverse(values.begin(), values.end());
        return values;
    }
    int swap_with = static_cast<int>(values.size()) - 1;
    while (values[swap_with] <= values[index]) swap_with--;
    std::swap(values[index], values[swap_with]);
    std::reverse(values.begin() + index + 1, values.end());
    return values;
}
```

