long long parseInteger(const std::string& text) {
    size_t i = 0;
    while (i < text.size() && text[i] == ' ') i++;
    int sign = 1;
    if (i < text.size() && (text[i] == '+' || text[i] == '-')) {
        if (text[i] == '-') sign = -1;
        i++;
    }
    long long value = 0;
    const long long LIMIT_MAX = 2147483647LL;
    const long long LIMIT_MIN = 2147483648LL;
    while (i < text.size() && text[i] >= '0' && text[i] <= '9') {
        value = value * 10 + (text[i] - '0');
        if (sign == 1 && value > LIMIT_MAX) return LIMIT_MAX;
        if (sign == -1 && value > LIMIT_MIN) return -LIMIT_MIN;
        i++;
    }
    return sign * value;
}
