function diffArrays(before, after) {
  const counts = new Map();
  for (const value of before) counts.set(value, (counts.get(value) || 0) + 1);
  const added = [];
  for (const value of after) {
    const current = counts.get(value) || 0;
    if (current > 0) counts.set(value, current - 1);
    else added.push(value);
  }
  const remaining = new Map();
  for (const value of after) remaining.set(value, (remaining.get(value) || 0) + 1);
  const removed = [];
  for (const value of before) {
    const current = remaining.get(value) || 0;
    if (current > 0) remaining.set(value, current - 1);
    else removed.push(value);
  }
  return { added, removed };
}
