type Brand<T, B> = T & { readonly __brand: B };
type OrderId = Brand<string, 'OrderId'>;

const PATTERN = /^ORD-(\d{4})$/;

function parseOrderId(raw: string): OrderId | null {
  if (typeof raw !== 'string' || !PATTERN.test(raw)) return null;
  return raw as OrderId;
}

function formatOrderId(id: OrderId): string {
  return id as string;
}

function nextOrderId(id: OrderId): OrderId {
  const match = PATTERN.exec(id as string);
  if (!match) throw new TypeError('malformed order id');
  const value = Number(match[1]) + 1;
  if (value > 9999) throw new RangeError('order id overflow');
  return parseOrderId('ORD-' + String(value).padStart(4, '0')) as OrderId;
}
