class Queue<T> {
  private items: (T | undefined)[] = [];
  private head = 0;

  enqueue(value: T): void {
    this.items.push(value);
  }

  dequeue(): T {
    if (this.head >= this.items.length) throw new RangeError('queue is empty');
    const value = this.items[this.head] as T;
    this.items[this.head] = undefined;
    this.head += 1;
    return value;
  }

  peek(): T | undefined {
    return this.head < this.items.length ? (this.items[this.head] as T) : undefined;
  }

  size(): number {
    return this.items.length - this.head;
  }

  toArray(): T[] {
    return this.items.slice(this.head) as T[];
  }
}
