```typescript
class TypedEmitter<Events extends Record<string, unknown>> {
  private handlers = new Map<keyof Events, ((payload: never) => void)[]>();

  on<K extends keyof Events>(name: K, handler: (payload: Events[K]) => void): () => void {
    const list = this.handlers.get(name) ?? [];
    list.push(handler as (payload: never) => void);
    this.handlers.set(name, list);
    return () => {
      this.off(name, handler);
    };
  }

  off<K extends keyof Events>(name: K, handler: (payload: Events[K]) => void): boolean {
    const list = this.handlers.get(name);
    if (!list) return false;
    const index = list.indexOf(handler as (payload: never) => void);
    if (index < 0) return false;
    list.splice(index, 1);
    return true;
  }

  emit<K extends keyof Events>(name: K, payload: Events[K]): number {
    const list = [...(this.handlers.get(name) ?? [])];
    let error: unknown;
    let hasError = false;
    for (const handler of list) {
      try {
        (handler as (value: Events[K]) => void)(payload);
      } catch (caught) {
        if (!hasError) {
          hasError = true;
          error = caught;
        }
      }
    }
    if (hasError) throw error;
    return list.length;
  }
}
