type Token =
  | { kind: 'number'; value: number }
  | { kind: 'name'; value: string }
  | { kind: 'op'; value: string }
  | { kind: 'paren'; value: string };

function tokenize(expression: string): Token[] {
  const tokens: Token[] = [];
  let index = 0;
  while (index < expression.length) {
    const ch = expression[index];
    if (/\s/.test(ch)) { index += 1; continue; }
    if (/[0-9]/.test(ch) || (ch === '.' && /[0-9]/.test(expression[index + 1] ?? ''))) {
      let text = '';
      let dots = 0;
      while (index < expression.length && (/[0-9]/.test(expression[index]) || expression[index] === '.')) {
        if (expression[index] === '.') dots += 1;
        text += expression[index];
        index += 1;
      }
      if (dots > 1) throw new SyntaxError('bad number at ' + index);
      tokens.push({ kind: 'number', value: Number(text) });
      continue;
    }
    if (/[A-Za-z_]/.test(ch)) {
      let text = '';
      while (index < expression.length && /[A-Za-z0-9_]/.test(expression[index])) {
        text += expression[index];
        index += 1;
      }
      tokens.push({ kind: 'name', value: text });
      continue;
    }
    if ('+-*/%,'.includes(ch)) {
      tokens.push({ kind: 'op', value: ch });
      index += 1;
      continue;
    }
    if ('()'.includes(ch)) {
      tokens.push({ kind: 'paren', value: ch });
      index += 1;
      continue;
    }
    throw new SyntaxError('unexpected character at ' + index);
  }
  return tokens;
}
