type Option<T> = { some: true; value: T } | { some: false };

function some<T>(value: T): Option<T> {
  return { some: true, value };
}

function none<T>(): Option<T> {
  return { some: false };
}

function mapOption<T, R>(option: Option<T>, fn: (value: T) => R): Option<R> {
  if (!option.some) return option;
  return some(fn(option.value));
}

function unwrapOr<T>(option: Option<T>, fallback: T): T {
  return option.some ? option.value : fallback;
}

function filterOption<T>(option: Option<T>, keep: (value: T) => boolean): Option<T> {
  if (!option.some) return option;
  return keep(option.value) ? option : none<T>();
}
