int countPrimes(int n) {
    if (n <= 2) return 0;
    std::vector<bool> composite(n, false);
    int count = 0;
    for (int value = 2; value < n; value++) {
        if (composite[value]) continue;
        count++;
        if (static_cast<long long>(value) * value < n) {
            for (long long multiple = static_cast<long long>(value) * value; multiple < n; multiple += value) {
                composite[static_cast<size_t>(multiple)] = true;
            }
        }
    }
    return count;
}
