std::vector<int> parseIntList(const std::string& text) {
    std::vector<int> out;
    size_t start = 0;
    while (start <= text.size()) {
        size_t comma = text.find(',', start);
        std::string piece = text.substr(start, comma == std::string::npos ? std::string::npos : comma - start);
        size_t begin = piece.find_first_not_of(" \t");
        size_t end = piece.find_last_not_of(" \t");
        if (begin != std::string::npos) {
            std::string trimmed = piece.substr(begin, end - begin + 1);
            size_t index = 0;
            int sign = 1;
            if (trimmed[index] == '+' || trimmed[index] == '-') {
                if (trimmed[index] == '-') sign = -1;
                index++;
            }
            if (index >= trimmed.size()) throw std::invalid_argument("bad number");
            int value = 0;
            for (; index < trimmed.size(); index++) {
                if (trimmed[index] < '0' || trimmed[index] > '9') throw std::invalid_argument("bad number");
                value = value * 10 + (trimmed[index] - '0');
            }
            out.push_back(sign * value);
        }
        if (comma == std::string::npos) break;
        start = comma + 1;
    }
    return out;
}
