double medianOfTwo(const std::vector<int>& a, const std::vector<int>& b) {
    if (a.size() > b.size()) return medianOfTwo(b, a);
    int m = static_cast<int>(a.size()), n = static_cast<int>(b.size());
    int low = 0, high = m;
    int half = (m + n + 1) / 2;
    while (low <= high) {
        int i = (low + high) / 2;
        int j = half - i;
        int leftA = (i == 0) ? std::numeric_limits<int>::min() : a[i - 1];
        int rightA = (i == m) ? std::numeric_limits<int>::max() : a[i];
        int leftB = (j == 0) ? std::numeric_limits<int>::min() : b[j - 1];
        int rightB = (j == n) ? std::numeric_limits<int>::max() : b[j];
        if (leftA <= rightB && leftB <= rightA) {
            if ((m + n) % 2 == 1) return std::max(leftA, leftB);
            return (std::max(leftA, leftB) + std::min(rightA, rightB)) / 2.0;
        }
        if (leftA > rightB) high = i - 1;
        else low = i + 1;
    }
    return 0.0;
}
