function parseDuration(text) {
  const units = { d: 86400, h: 3600, m: 60, s: 1 };
  const order = ['d', 'h', 'm', 's'];
  const pattern = /^(\d+)([dhms])$/;
  if (text === '') throw new SyntaxError('empty duration');
  const parts = text.match(/\d+[dhms]/g) || [];
  if (parts.join('') !== text) throw new SyntaxError('malformed duration');
  let total = 0;
  let lastIndex = -1;
  for (const part of parts) {
    const match = pattern.exec(part);
    const amount = Number(match[1]);
    const unit = match[2];
    const index = order.indexOf(unit);
    if (index <= lastIndex) throw new SyntaxError('units out of order');
    lastIndex = index;
    total += amount * units[unit];
  }
  return total;
}
