"""Base-36 encoding for short identifiers."""

DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def to_base36(value):
    """Encode a non-negative integer in base 36."""
    if value < 0:
        raise ValueError("negative value")
    if value == 0:
        return "0"
    out = []
    while value:
        value, remainder = divmod(value, 36)
        out.append(DIGITS[remainder])
    return "".join(out)


def from_base36(text):
    """Decode a base-36 string."""
    value = 0
    for ch in text.lower():
        value = value * 36 + DIGITS.index(ch)
    return value


def round_trip(value):
    """Encode then decode, for sanity checks."""
    return from_base36(to_base36(value))

