class TokenBucket {
  private readonly capacity: number;
  private readonly rate: number;
  private tokens: number;
  private last: number;

  constructor(capacity: number, refillPerSecond: number, now: number) {
    if (!(capacity > 0)) throw new RangeError('capacity must be positive');
    if (refillPerSecond < 0) throw new RangeError('rate must be non-negative');
    this.capacity = capacity;
    this.rate = refillPerSecond;
    this.tokens = capacity;
    this.last = now;
  }

  private refill(now: number): void {
    if (now < this.last) throw new RangeError('time must not go backwards');
    const gained = ((now - this.last) / 1000) * this.rate;
    this.tokens = Math.min(this.capacity, this.tokens + gained);
    this.last = now;
  }

  available(now: number): number {
    this.refill(now);
    return this.tokens;
  }

  tryRemove(tokens: number, now: number): boolean {
    if (!(tokens > 0)) throw new RangeError('tokens must be positive');
    this.refill(now);
    if (this.tokens + 1e-9 < tokens) return false;
    this.tokens -= tokens;
    return true;
  }
}
