function addMatrices(a: number[][], b: number[][]): number[][] {
  if (a.length !== b.length) throw new RangeError('shape mismatch');
  return a.map((row, r) => {
    if (row.length !== b[r].length) throw new RangeError('shape mismatch');
    return row.map((value, c) => value + b[r][c]);
  });
}

function multiplyMatrices(a: number[][], b: number[][]): number[][] {
  if (a.length === 0) return [];
  if (a[0].length !== b.length) throw new RangeError('shape mismatch');
  const cols = b.length === 0 ? 0 : b[0].length;
  return a.map(row => {
    const out: number[] = [];
    for (let c = 0; c < cols; c++) {
      let total = 0;
      for (let k = 0; k < b.length; k++) total += row[k] * b[k][c];
      out.push(total);
    }
    return out;
  });
}

function transposeMatrix(a: number[][]): number[][] {
  if (a.length === 0 || a[0].length === 0) return [];
  return a[0].map((_, c) => a.map(row => row[c]));
}
