type FieldType = 'string' | 'number' | 'boolean';

function validateRecord(value: unknown, schema: Record<string, FieldType>): string[] {
  const missing: string[] = [];
  const source = (value !== null && typeof value === 'object') ? value as Record<string, unknown> : null;
  for (const key of Object.keys(schema)) {
    if (source === null || !Object.prototype.hasOwnProperty.call(source, key)) {
      missing.push(key);
      continue;
    }
    const field = source[key];
    const expected = schema[key];
    if (expected === 'number') {
      if (typeof field !== 'number' || Number.isNaN(field)) missing.push(key);
    } else if (expected === 'boolean') {
      if (typeof field !== 'boolean') missing.push(key);
    } else if (typeof field !== 'string') {
      missing.push(key);
    }
  }
  return missing;
}
