function weightedAverage(entries: readonly [number, number][]): number {
  let total = 0;
  let weightSum = 0;
  for (const [value, weight] of entries) {
    if (!Number.isFinite(value) || !Number.isFinite(weight)) throw new TypeError('finite numbers expected');
    if (weight < 0) throw new RangeError('weights must be non-negative');
