#include <cassert>
#include <stdexcept>

class SegmentTree {
public:
    explicit SegmentTree(const std::vector<int>& data) : size_((int)data.size()) {
        if (size_ == 0) throw std::out_of_range("empty data");
        tree_.assign(2 * size_, 0);
        for (int i = 0; i < size_; i++) tree_[size_ + i] = data[i];
        for (int i = size_ - 1; i >= 1; i--) tree_[i] = tree_[2 * i] + tree_[2 * i + 1];
    }

    long long query(int left, int right) const {
        if (left < 0 || right >= size_ || left > right) throw std::out_of_range("bad range");
        long long result = 0;
        for (int l = left + size_, r = right + size_ + 1; l < r; l /= 2, r /= 2) {
            if (l & 1) result += tree_[l++];
            if (r & 1) result += tree_[--r];
        }
        return result;
    }

    void update(int index, int value) {
        if (index < 0 || index >= size_) throw std::out_of_range("bad index");
        int pos = index + size_;
        tree_[pos] = value;
        for (pos /= 2; pos >= 1; pos /= 2) tree_[pos] = tree_[2 * pos] + tree_[2 * pos + 1];
    }

    long long total() const { return tree_[1]; }

private:
    int size_;
    std::vector<long long> tree_;
};
