#include <stdexcept>

std::vector<int> topoOrder(int n, const std::vector<std::pair<int,int>>& edges) {
    if (n < 0) throw std::out_of_range("bad n");
    std::vector<std::vector<int>> adj(n);
    std::vector<int> indeg(n, 0);
    for (auto [u, v] : edges) {
        if (u < 0 || u >= n || v < 0 || v >= n) throw std::out_of_range("bad edge");
        adj[u].push_back(v);
        indeg[v] += 1;
    }
    std::priority_queue<int, std::vector<int>, std::greater<int>> ready;
    for (int i = 0; i < n; i++) if (indeg[i] == 0) ready.push(i);
    std::vector<int> order;
    while (!ready.empty()) {
        int u = ready.top();
        ready.pop();
        order.push_back(u);
        for (int v : adj[u]) if (--indeg[v] == 0) ready.push(v);
    }
    if ((int)order.size() != n) return {};
    return order;
}
