int countOccurrences(const std::string& text, const std::string& pattern) {
    if (pattern.empty() || text.size() < pattern.size()) return 0;
    std::vector<size_t> fail(pattern.size(), 0);
    for (size_t i = 1; i < pattern.size(); i++) {
        size_t k = fail[i - 1];
        while (k > 0 && pattern[i] != pattern[k]) k = fail[k - 1];
        if (pattern[i] == pattern[k]) k += 1;
        fail[i] = k;
    }
    int count = 0;
    size_t k = 0;
    for (char ch : text) {
        while (k > 0 && ch != pattern[k]) k = fail[k - 1];
        if (ch == pattern[k]) k += 1;
        if (k == pattern.size()) {
            count += 1;
            k = fail[k - 1];
        }
    }
    return count;
}
