const SIMPLE_ESCAPES = { n: '\n', t: '\t', r: '\r', '\\': '\\' };

function decodeEscapes(text) {
  let out = '';
  let i = 0;
  const src = String(text);
  while (i < src.length) {
    const ch = src[i];
    if (ch !== '\\') {
      out += ch;
      i += 1;
      continue;
    }
    if (i + 1 >= src.length) throw new SyntaxError('bad escape');
    const next = src[i + 1];
    if (next in SIMPLE_ESCAPES) {
      out += SIMPLE_ESCAPES[next];
      i += 2;
      continue;
