      const hex = src.slice(i + 2, i + 6);
      if (!/^[0-9a-fA-F]{4}$/.test(hex)) throw new SyntaxError('bad escape');
      out += String.fromCharCode(parseInt(hex, 16));
      i += 6;
      continue;
    }
    throw new SyntaxError('bad escape');
  }
  return out;
