function histogram(values, bucketSize) {
  if (!(bucketSize > 0) || !Number.isInteger(bucketSize)) throw new RangeError('bucketSize must be a positive integer');
  if (values.length === 0) return [];
  for (const value of values) {
    if (!Number.isInteger(value) || value < 0) throw new RangeError('values must be non-negative integers');
  }
  const highest = Math.max(...values);
  const lastIndex = Math.floor(highest / bucketSize);
  const counts = new Array(lastIndex + 1).fill(0);
  for (const value of values) counts[Math.floor(value / bucketSize)] += 1;
  return counts.map((count, index) => [index * bucketSize, (index + 1) * bucketSize, count]);
}
