def is_valid_email(address):
    """One @, a dotted domain that does not start or end with a dot, no spaces."""
    if not isinstance(address, str) or " " in address:
        return False
    if address.count("@") != 1:
        return False
    local, domain = address.split("@")
    if not local or not domain:
        return False
    return "." in domain


