"""Percentage rollouts keyed by user id."""


def bucket_for(user_id):
    """A stable bucket in 0..99."""
    total = 0
    for ch in user_id:
        total = (total * 31 + ord(ch)) % 100
    return total


def enabled(user_id, percent):
