#include <cassert>
#include <stdexcept>
#include <list>
#include <unordered_map>

class LRUCache {
public:
    explicit LRUCache(int capacity) : capacity_(capacity) {
        if (capacity < 1) throw std::invalid_argument("capacity must be at least 1");
    }

    int get(int key) {
        auto it = where_.find(key);
        if (it == where_.end()) return -1;
        order_.splice(order_.begin(), order_, it->second);
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = where_.find(key);
        if (it != where_.end()) {
            it->second->second = value;
            order_.splice(order_.begin(), order_, it->second);
            return;
        }
        if ((int)order_.size() == capacity_) {
            where_.erase(order_.back().first);
            order_.pop_back();
        }
        order_.push_front({key, value});
        where_[key] = order_.begin();
    }

    int size() const { return (int)order_.size(); }

private:
    int capacity_;
    std::list<std::pair<int,int>> order_;
    std::unordered_map<int, std::list<std::pair<int,int>>::iterator> where_;
};
