#include <cassert>
#include <stdexcept>

struct Node {
    int value;
    Node* left;
    Node* right;
};

static void writeNode(const Node* node, std::string& out) {
    if (!out.empty()) out.push_back(',');
    if (node == nullptr) {
        out.push_back('#');
        return;
    }
    out += std::to_string(node->value);
    writeNode(node->left, out);
    writeNode(node->right, out);
}

std::string serialize(const Node* root) {
    std::string out;
    writeNode(root, out);
    return out;
}

static Node* readNode(const std::vector<std::string>& parts, size_t& index) {
    if (index >= parts.size()) throw std::invalid_argument("truncated tree");
    const std::string piece = parts[index++];
    if (piece == "#") return nullptr;
    if (piece.empty()) throw std::invalid_argument("empty field");
    for (size_t i = 0; i < piece.size(); i++) {
        char ch = piece[i];
        if (i == 0 && (ch == '-' || ch == '+')) continue;
        if (ch < '0' || ch > '9') throw std::invalid_argument("bad value");
    }
    Node* node = new Node{std::stoi(piece), nullptr, nullptr};
    node->left = readNode(parts, index);
    node->right = readNode(parts, index);
    return node;
}

Node* deserialize(const std::string& text) {
    std::vector<std::string> parts;
    std::string current;
    for (char ch : text) {
        if (ch == ',') {
            parts.push_back(current);
            current.clear();
        } else {
            current.push_back(ch);
        }
    }
    parts.push_back(current);
    size_t index = 0;
    Node* root = readNode(parts, index);
    if (index != parts.size()) throw std::invalid_argument("trailing data");
    return root;
}
