#include <cassert>
#include <stdexcept>

int minCoins(const std::vector<int>& coins, int amount) {
    if (amount < 0) throw std::invalid_argument("negative amount");
    for (int coin : coins) if (coin < 1) throw std::invalid_argument("coin must be positive");
    const int INF = amount + 1;
    std::vector<int> best(amount + 1, INF);
    best[0] = 0;
    for (int value = 1; value <= amount; value++) {
        for (int coin : coins) {
            if (coin > value) continue;
            if (best[value - coin] + 1 < best[value]) best[value] = best[value - coin] + 1;
        }
    }
    return best[amount] >= INF ? -1 : best[amount];
}
