import heapq
import itertools


class LazyQueue:
    def __init__(self):
        self._heap = []
        self._order = itertools.count()
        self._live = {}
        self._tombstones = 0

    def push(self, item, priority):
        heapq.heappush(self._heap, (priority, next(self._order), item))
        self._live[item] = True

    def pop(self):
        while self._heap:
            priority, _, item = heapq.heappop(self._heap)
            if self._live.get(item):
                del self._live[item]
                return item
            self._tombstones += 1
        raise IndexError("pop from empty queue")

    def discard(self, item):
        if self._live.get(item):
            del self._live[item]

    def __len__(self):
        return len(self._live)
