class BloomFilter:
    def __init__(self, size, hashes):
        if size <= 0 or hashes <= 0:
            raise ValueError("size and hashes must be positive")
        self.size = size
        self.hashes = hashes
        self.bits = bytearray(size)

    def _indexes(self, item):
        base = sum((index + 1) * ord(ch) for index, ch in enumerate(item))
        return [(base * (k + 1) + k) % self.size for k in range(self.hashes)]

    def add(self, item):
        for index in self._indexes(item):
            self.bits[index] = 1

    def contains(self, item):
        # True when every bit for the item is set, so no false negatives.

        return all(self.bits[index] for index in self._indexes(item))

    def __contains__(self, item):
        return self.contains(item)
