class TtlCache {
  constructor(ttl, now) {
    if (!(ttl > 0)) throw new RangeError('ttl must be positive');
    this.ttl = ttl;
    this.start = now;
    this.entries = new Map();
  }

  set(key, value, now) {
    this.entries.set(key, { value, at: now });
  }

  get(key, now) {
    const entry = this.entries.get(key);
    if (!entry) return undefined;
    if (now - entry.at >= this.ttl) {
      this.entries.delete(key);
      return undefined;
    }
    return entry.value;
  }

  has(key, now) {
    const entry = this.entries.get(key);
    return entry !== undefined && now - entry.at < this.ttl;
  }

  size(now) {
    for (const [key, entry] of [...this.entries]) {
      if (now - entry.at >= this.ttl) this.entries.delete(key);
    }
    return this.entries.size;
