```typescript
type Shape =
  | { kind: 'circle'; radius: number }
  | { kind: 'rect'; width: number; height: number }
  | { kind: 'triangle'; base: number; height: number };

function shapeArea(shape: Shape): number {
  const check = (value: number) => {
    if (!Number.isFinite(value) || value < 0) throw new RangeError('dimensions must be non-negative');
    return value;
  };
  switch (shape.kind) {
    case 'circle':
      return Math.PI * check(shape.radius) ** 2;
    case 'rect':
      return check(shape.width) * check(shape.height);
    case 'triangle':
      return (check(shape.base) * check(shape.height)) / 2;
    default:
      throw new TypeError('unknown shape');
  }
}
```

