function rangeStep(start: number, stop: number, step = 1): number[] {
  for (const value of [start, stop, step]) {
    if (!Number.isFinite(value)) throw new TypeError('finite numbers expected');
  }
  if (step === 0) throw new RangeError('step must not be zero');
  const out: number[] = [];
  if (step > 0) {
    for (let value = start; value < stop; value += step) out.push(value);
  } else {
    for (let value = start; value > stop; value += step) out.push(value);
  }
  return out;
}
