#include <cassert>
#include <stdexcept>

int longestKDistinct(const std::string& text, int k) {
    if (k < 0) throw std::invalid_argument("negative k");
    if (k == 0) return 0;
    std::vector<int> count(256, 0);
    int distinct = 0, best = 0, left = 0;
    for (int right = 0; right < (int)text.size(); right++) {
        unsigned char ch = (unsigned char)text[right];
        if (count[ch]++ == 0) distinct++;
        while (distinct > k) {
            unsigned char out = (unsigned char)text[left++];
            if (--count[out] == 0) distinct--;
        }
        best = std::max(best, right - left + 1);
    }
    return best;
}
