int countTriples(std::vector<int> values, int target) {
    std::sort(values.begin(), values.end());
    int count = 0;
    const int n = (int)values.size();
    for (int i = 0; i + 2 < n; i++) {
        int left = i + 1, right = n - 1;
        while (left < right) {
            long long sum = (long long)values[i] + values[left] + values[right];
            if (sum == target) {
                if (values[left] == values[right]) {
                    int span = right - left + 1;
                    count += span * (span - 1) / 2;
                    break;
                }
                int leftCount = 1, rightCount = 1;
                while (left + 1 < right && values[left + 1] == values[left]) { left++; leftCount++; }
                while (right - 1 > left && values[right - 1] == values[right]) { right--; rightCount++; }
                count += leftCount * rightCount;
                left++;
                right--;
            } else if (sum < target) {
                left++;
            } else {
                right--;
            }
        }
    }
    return count;
}
