#include <cassert>
#include <stdexcept>

std::vector<int> grayCode(int bits) {
    if (bits < 0) throw std::invalid_argument("negative bits");
    std::vector<int> out;
    const long long size = 1LL << bits;
    out.reserve((size_t)size);
    for (long long i = 0; i < size; i++) {
        out.push_back((int)(i ^ (i >> 1)));
    }
    return out;
}
