#include <cassert>
#include <stdexcept>

std::vector<int> parseIntList(const std::string& text) {
    std::vector<int> out;
    if (text.empty()) return out;
    size_t start = 0;
    while (true) {
        size_t comma = text.find(',', start);
        std::string piece = text.substr(start, comma == std::string::npos ? std::string::npos : comma - start);
        size_t first = piece.find_first_not_of(" \t");
        size_t last = piece.find_last_not_of(" \t");
        if (first == std::string::npos) throw std::invalid_argument("empty item");
        piece = piece.substr(first, last - first + 1);
        size_t offset = 0;
        bool negative = false;
        if (piece[0] == '-') { negative = true; offset = 1; }
        if (offset >= piece.size()) throw std::invalid_argument("missing digits");
        for (size_t i = offset; i < piece.size(); i++) {
            if (piece[i] < '0' || piece[i] > '9') throw std::invalid_argument("bad digit");
        }
        long long value = std::stoll(piece);
        if (value < -2147483648LL || value > 2147483647LL) throw std::invalid_argument("out of range");
        out.push_back((int)value);
        if (comma == std::string::npos) break;
        start = comma + 1;
    }
    return out;
}
