std::vector<std::string> groupAnagrams(const std::vector<std::string>& words) {
    std::map<std::string, std::vector<std::string>> groups;
    for (const std::string& word : words) {
        std::string key = word;
        std::sort(key.begin(), key.end());
        groups[key].push_back(word);
    }
    std::vector<std::vector<std::string>> prepared;
    for (auto& entry : groups) {
        std::vector<std::string> group = entry.second;
        std::sort(group.begin(), group.end());
        prepared.push_back(group);
    }
    std::sort(prepared.begin(), prepared.end(), [](const auto& a, const auto& b) {
        return a.front() < b.front();
    });
    std::vector<std::string> out;
    for (const auto& group : prepared) {
        std::string joined;
        for (size_t i = 0; i < group.size(); i++) {
            if (i) joined.push_back(',');
            joined += group[i];
        }
        out.push_back(joined);
    }
    return out;
}
