def _trim(coefficients):
    end = len(coefficients)
    while end > 0 and coefficients[end - 1] == 0:
        end -= 1
    return coefficients[:end]


def poly_add(a, b):
    size = max(len(a), len(b))
    out = [0] * size
    for index in range(size):
        out[index] = (a[index] if index < len(a) else 0) + (b[index] if index < len(b) else 0)
    return _trim(out)


def poly_mul(a, b):
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, left in enumerate(a):
        if left == 0:
            continue
        for j, right in enumerate(b):
            out[i + j] += left * right
    return _trim(out)
