def count_ways(coins, amount):
    if amount < 0:
        raise ValueError("negative amount")
    for coin in coins:
        if coin <= 0:
            raise ValueError("coins must be positive")
    ways = [0] * (amount + 1)
    ways[0] = 1
    for coin in coins:
        for value in range(coin, amount + 1):
            ways[value] += ways[value - coin]
    return ways[amount]
