from functools import lru_cache


def balanced_with_wildcards(text):
    @lru_cache(maxsize=None)
    def check(index, depth):
        if depth < 0:
            return False
        if index == len(text):
            return depth == 0
        char = text[index]
        if char == "(":
            return check(index + 1, depth + 1)
        if char == ")":
            return check(index + 1, depth - 1)
        if char == "*":
            return check(index + 1, depth) or check(index + 1, depth + 1) or check(index + 1, depth - 1)
        return check(index + 1, depth)

    return check(0, 0)
