from collections import deque


def allow_requests(timestamps, limit, window):
    if limit < 1:
        raise ValueError("limit must be at least 1")
    if window < 0:
        raise ValueError("window must not be negative")
    accepted = deque()
    results = []
    for moment in timestamps:
