function hopsBetween(graph, start, goal) {
  if (start === goal) return 0;
  if (!Object.prototype.hasOwnProperty.call(graph, start)) return -1;
  const seen = new Set([start]);
  let frontier = [start];
  let depth = 0;
  while (frontier.length > 0) {
    const next = [];
    depth += 1;
    for (const node of frontier) {
      for (const neighbour of graph[node] ?? []) {
        if (neighbour === goal) return depth;
        if (seen.has(neighbour)) continue;
        seen.add(neighbour);
        next.push(neighbour);
      }
    }
    frontier = next;
  }
  return -1;
}
