function topologicalOrder(nodes, edges) {
  if (!Number.isInteger(nodes) || nodes < 0) throw new RangeError('bad node count');
  const adjacency = Array.from({ length: nodes }, () => []);
  const indegree = new Array(nodes).fill(0);
  for (const [from, to] of edges) {
    if (from < 0 || from >= nodes || to < 0 || to >= nodes) throw new RangeError('bad edge');
    adjacency[from].push(to);
    indegree[to] += 1;
  }
  const ready = [];
  for (let i = 0; i < nodes; i++) if (indegree[i] === 0) ready.push(i);
  ready.sort((a, b) => a - b);
  const order = [];
  while (ready.length > 0) {
    const node = ready.shift();
    order.push(node);
    for (const next of adjacency[node]) {
      indegree[next] -= 1;
      if (indegree[next] === 0) {
        ready.push(next);
        ready.sort((a, b) => a - b);
      }
    }
  }
  return order.length === nodes ? order : null;
}
```

