```typescript
function memoizeBy<T, K, R>(fn: (value: T) => R, keyOf: (value: T) => K) {
  const cache = new Map<K, R>();
  let calls = 0;
  const wrapper = (value: T): R => {
    const key = keyOf(value);
    if (cache.has(key)) return cache.get(key) as R;
    const result = fn(value);
    calls += 1;
    cache.set(key, result);
    return result;
  };
  wrapper.calls = () => calls;
  return wrapper;
}
```

