function allPaths(graph: Map<string, string[]>, start: string, goal: string): string[][] {
  const found: string[][] = [];
  const walk = (node: string, path: string[]) => {
    if (node === goal) {
      found.push([...path]);
      return;
    }
    for (const next of graph.get(node) ?? []) {
      if (path.includes(next)) continue;
      path.push(next);
      walk(next, path);
      path.pop();
    }
  };
  if (!graph.has(start) && start !== goal) return [];
  walk(start, [start]);
  return found.sort((a, b) => {
    const left = a.join('/');
    const right = b.join('/');
    return left < right ? -1 : left > right ? 1 : 0;
  });
}
