function singleFlight<T>(loader: () => Promise<T>) {
  let pending: Promise<T> | null = null;
  let calls = 0;
  const run = () => {
    if (pending === null) {
      calls += 1;
      pending = loader().finally(() => {
        pending = null;
      });
    }
    return pending;
  };
  run.calls = () => calls;
  return run;
}
