function checkRange(range: readonly [string, string]): void {
  const [start, end] = range;
  if (start > end) throw new RangeError('start after end');
}

function overlaps(a: readonly [string, string], b: readonly [string, string]): boolean {
  checkRange(a);
  checkRange(b);
  return a[0] <= b[1] && b[0] <= a[1];
}

function overlapDays(a: readonly [string, string], b: readonly [string, string]): number {
  if (!overlaps(a, b)) return 0;
  const start = a[0] > b[0] ? a[0] : b[0];
  const end = a[1] < b[1] ? a[1] : b[1];
  const from = Date.parse(start + 'T00:00:00Z');
  const to = Date.parse(end + 'T00:00:00Z');
  return Math.round((to - from) / 86400000) + 1;
}
