    long long n = std::llabs(numerator), d = std::llabs(denominator);
    out += std::to_string(n / d);
    long long remainder = n % d;
    if (remainder == 0) return out;
    out.push_back('.');
    std::unordered_map<long long, int> seen;
    std::string digits;
    while (remainder != 0 && seen.find(remainder) == seen.end()) {
        seen[remainder] = (int)digits.size();
        remainder *= 10;
        digits.push_back(char('0' + remainder / d));
        remainder %= d;
    }
    if (remainder == 0) {
        out += digits;
    } else {
        int start = seen[remainder];
        out += digits.substr(0, start) + "(" + digits.substr(start) + ")";
    }
    return out;
}
