bool wordBreak(const std::string& text, const std::vector<std::string>& words) {
    const int n = (int)text.size();
    std::vector<char> reachable(n + 1, 0);
    reachable[0] = 1;
    for (int end = 1; end <= n; end++) {
        for (const std::string& word : words) {
            int size = (int)word.size();
            if (size == 0 || size > end) continue;
            if (!reachable[end - size]) continue;
            if (text.compare(end - size, size, word) == 0) {
                reachable[end] = 1;
                break;
            }
        }
    }
    return reachable[n] != 0;
}
