std::vector<int> radixSort(const std::vector<int>& values) {
    for (int value : values) if (value < 0) throw std::invalid_argument("negative value");
    std::vector<unsigned int> data(values.begin(), values.end());
    std::vector<unsigned int> buffer(data.size());
    for (int shift = 0; shift < 32; shift += 8) {
        std::vector<int> counts(257, 0);
        for (unsigned int value : data) counts[((value >> shift) & 0xFF) + 1] += 1;
        for (int i = 1; i < 257; i++) counts[i] += counts[i - 1];
        for (unsigned int value : data) buffer[counts[(value >> shift) & 0xFF]++] = value;
