def topological_layers(nodes, edges):
    if nodes < 0:
        raise ValueError("negative node count")
    adjacency = [[] for _ in range(nodes)]
    indegree = [0] * nodes
    for before, after in edges:
        if not (0 <= before < nodes and 0 <= after < nodes):
            raise ValueError("bad edge")
        adjacency[before].append(after)
        indegree[after] += 1
    layers = []
    ready = [node for node in range(nodes) if indegree[node] == 0]
    seen = 0
    while ready:
        layer = sorted(ready)
        layers.append(layer)
        seen += len(layer)
        nxt = []
        for node in layer:
            for after in adjacency[node]:
                indegree[after] -= 1
                if indegree[after] == 0:
                    nxt.append(after)
        ready = nxt
    if seen != nodes:
        raise ValueError("cycle detected")
    return layers
