    if not cleaned.isdigit():
        raise ValueError("digits only")
    return cleaned


def isbn13_valid(text):
    cleaned = text.replace("-", "").replace(" ", "")
    if not cleaned.isdigit() or len(cleaned) != 13:
        return False
    total = 0
    for index, ch in enumerate(cleaned):
        weight = 1 if index % 2 == 0 else 3
        total += weight * int(ch)
    return total % 10 == 0


def isbn13_check_digit(first12):
    cleaned = _digits(first12)
    if len(cleaned) != 12:
        raise ValueError("need 12 digits")
    total = 0
    for index, ch in enumerate(cleaned):
        weight = 1 if index % 2 == 0 else 3
        total += weight * int(ch)
    return (10 - total % 10) % 10
