"""Rotating lists."""


def rotate_right(values, steps):
    """Rotate values to the right by steps positions."""
    if not values:
        return []
    shift = steps % (len(values) + 1)
    if shift == 0:
        return list(values)
    return values[-shift:] + values[:-shift]


def rotate_left(values, steps):
    """Rotate values to the left by steps positions."""
    if not values:
        return []
    shift = (steps % len(values) + len(values)) % len(values)
    return values[shift:] + values[:shift]

