class UnionFind {
  constructor(size) {
    if (!Number.isInteger(size) || size < 1) throw new RangeError('size must be at least 1');
    this.parent = Array.from({ length: size }, (_, index) => index);
    this.sizes = new Array(size).fill(1);
    this.count = size;
  }

  check(index) {
    if (!Number.isInteger(index) || index < 0 || index >= this.parent.length) throw new RangeError('bad index');
  }

  find(x) {
    this.check(x);
    let root = x;
    while (this.parent[root] !== root) root = this.parent[root];
    let node = x;
    while (this.parent[node] !== root) {
      const next = this.parent[node];
      this.parent[node] = root;
      node = next;
    }
    return root;
  }

  union(a, b) {
    let left = this.find(a);
    let right = this.find(b);
    if (left === right) return false;
    if (this.sizes[left] < this.sizes[right]) [left, right] = [right, left];
    this.parent[right] = left;
    this.sizes[left] += this.sizes[right];
    this.count -= 1;
    return true;
  }

  connected(a, b) {
    return this.find(a) === this.find(b);
  }

  components() {
    return this.count;
  }
}
```

