function binaryGap(value) {
  if (!Number.isInteger(value) || value < 0) throw new RangeError('non-negative integers only');
  let best = 0;
  let current = -1;
  let bits = value;
  let position = 0;
  while (bits > 0) {
    if (bits & 1) {
      if (current >= 0) best = Math.max(best, position - current);
      current = position;
    }
    bits >>>= 1;
    position += 1;
  }
  return best;
}
