function roundHalfEven(value, digits = 0) {
  if (!Number.isFinite(value)) throw new TypeError('finite numbers expected');
  if (!Number.isInteger(digits) || digits < 0 || digits > 6) throw new RangeError('digits out of range');
  const factor = 10 ** digits;
