function quote(value: unknown): string {
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  return "'" + String(value).split("'").join("''") + "'";
}

function buildQuery<T extends Record<string, unknown>>(table: string, filters: Partial<T>): string {
  if (table === '') throw new RangeError('table name required');
  const clauses: string[] = [];
  for (const key of Object.keys(filters)) {
    const value = filters[key];
    if (value === undefined) continue;
    if (value === null) clauses.push(key + ' IS NULL');
    else clauses.push(key + ' = ' + quote(value));
  }
  if (clauses.length === 0) return 'SELECT * FROM ' + table;
  return 'SELECT * FROM ' + table + ' WHERE ' + clauses.join(' AND ');
}
