std::pair<int,int> twoSum(const std::vector<int>& sorted, int target) {
    int left = 0;
    int right = (int)sorted.size() - 1;
    while (left < right) {
        long long sum = (long long)sorted[left] + sorted[right];
        if (sum == target) return {left, right};
        if (sum < target) left++;
        else right--;
    }
    return {-1, -1};
}
