std::vector<int> sortColors(std::vector<int> values) {
    for (int value : values) {
        if (value < 0 || value > 2) throw std::invalid_argument("values must be 0, 1 or 2");
    }
    int low = 0, mid = 0, high = (int)values.size() - 1;
    while (mid <= high) {
        if (values[mid] == 0) {
            std::swap(values[low], values[mid]);
            low++;
            mid++;
        } else if (values[mid] == 1) {
            mid++;
        } else {
            std::swap(values[mid], values[high]);
            high--;
