def mst_weight(nodes, edges):
    if nodes <= 0:
        raise ValueError("node count must be positive")
    for u, v, _ in edges:
        if not (0 <= u < nodes and 0 <= v < nodes):
            raise ValueError("bad endpoint")
    parent = list(range(nodes))
    sizes = [1] * nodes

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total = 0
    used = 0
    for u, v, weight in sorted(edges, key=lambda edge: edge[2]):
        left, right = find(u), find(v)
        if left == right:
            continue
        if sizes[left] < sizes[right]:
            left, right = right, left
        parent[right] = left
        sizes[left] += sizes[right]
        total += weight
        used += 1
        if used == nodes - 1:
            break
    return total if used == nodes - 1 else None
```

