def insert_index(sorted_values, value):
    """The index where the value keeps the list sorted, before equals."""
    low, high = 0, len(sorted_values)
    while low < high:
        mid = (low + high) // 2
        if sorted_values[mid] <= value:
            low = mid + 1
        else:
            high = mid
    return low


def insert(values, new_value):
    """A new sorted list with the value inserted."""
    index = insert_index(values, new_value)
    return values[:index] + [new_value] + values[index:]

