function validateRange(value: number, min: number, max: number, step?: number): string[] {
  if (min > max) throw new RangeError('min must not exceed max');
  const problems: string[] = [];
  if (!Number.isFinite(value)) {
    problems.push('not a number');
    return problems;
  }
  if (value < min) problems.push('below minimum');
  if (value > max) problems.push('above maximum');
  if (step !== undefined && step > 0) {
    const remainder = Math.abs((value - min) % step);
    if (remainder > 1e-9 && Math.abs(remainder - step) > 1e-9) problems.push('not on step');
  }
  return problems;
}
