): R[] {
  const out: R[] = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (compare(left[i], right[j]) <= 0) {
      out.push(combine(left[i]));
      i += 1;
    } else {
      out.push(combine(right[j]));
      j += 1;
    }
