class IntervalSet {
  private ranges: [number, number][] = [];

  add(start: number, end: number): void {
    if (start > end) throw new RangeError('start after end');
    if (start === end) return;
    const all = [...this.ranges, [start, end] as [number, number]].sort((a, b) => a[0] - b[0]);
    const merged: [number, number][] = [];
    for (const range of all) {
      const last = merged[merged.length - 1];
      if (last && range[0] <= last[1]) last[1] = Math.max(last[1], range[1]);
      else merged.push([range[0], range[1]]);
    }
    this.ranges = merged;
  }

  contains(value: number): boolean {
    return this.ranges.some(([start, end]) => value >= start && value < end);
  }

  toArray(): [number, number][] {
    return this.ranges.map(([start, end]) => [start, end] as [number, number]);
  }

  length(): number {
    return this.ranges.reduce((total, [start, end]) => total + (end - start), 0);
  }
}
