#include <cassert>
#include <vector>
#include <deque>
#include <stdexcept>

std::vector<int> window_max(const std::vector<int>& values, int k) {
    if (k < 1) throw std::invalid_argument("k must be positive");
    if (values.empty()) return {};
    if (static_cast<std::size_t>(k) > values.size()) throw std::invalid_argument("k too large");
    std::vector<int> out;
    std::deque<std::size_t> window;
    for (std::size_t i = 0; i < values.size(); ++i) {
        while (!window.empty() && values[window.back()] <= values[i]) window.pop_back();
        window.push_back(i);
        if (window.front() + static_cast<std::size_t>(k) <= i) window.pop_front();
        if (i + 1 >= static_cast<std::size_t>(k)) out.push_back(values[window.front()]);
    }
    return out;
}
