long long count_subarrays(const std::vector<int>& values, int target) {
    std::unordered_map<long long, long long> seen;
    seen[0] = 1;
    long long prefix = 0;
    long long total = 0;
    for (int value : values) {
        prefix += value;
        auto it = seen.find(prefix - target);
        if (it != seen.end()) total += it->second;
        ++seen[prefix];
    }
    return total;
}
