#include <cassert>
#include <string>
#include <stdexcept>

std::string rle_encode(const std::string& text) {
    std::string out;
    std::size_t index = 0;
    while (index < text.size()) {
        std::size_t run = 1;
        while (index + run < text.size() && text[index + run] == text[index]) ++run;
        out.push_back(text[index]);
        out += std::to_string(run);
        index += run;
    }
    return out;
}

std::string rle_decode(const std::string& text) {
    std::string out;
    std::size_t index = 0;
    while (index < text.size()) {
        char symbol = text[index];
        if (symbol >= '0' && symbol <= '9') throw std::invalid_argument("missing symbol");
        ++index;
        std::size_t start = index;
        long long count = 0;
        while (index < text.size() && text[index] >= '0' && text[index] <= '9') {
            count = count * 10 + (text[index] - '0');
            ++index;
        }
        if (index == start || count == 0) throw std::invalid_argument("missing count");
        out.append(static_cast<std::size_t>(count), symbol);
    }
    return out;
}
