#include <vector>
#include <utility>

std::pair<int, int> two_sum_sorted(const std::vector<int>& values, int target) {
    int left = 0;
    int right = static_cast<int>(values.size()) - 1;
    while (left < right) {
        long long sum = static_cast<long long>(values[left]) + values[right];
        if (sum == target) return {left + 1, right + 1};
        if (sum < target) ++left;
        else --right;
    }
    return {-1, -1};
}
```

