def longest_common_prefix(words):
    if not words:
        return ''
    prefix = words[0]
    for word in words[1:]:
        limit = min(len(prefix), len(word))
        length = 0
        while length < limit and prefix[length] == word[length]:
            length += 1
        prefix = prefix[:length]
        if not prefix:
            return ''
    return prefix
