def can_segment(text, words):
    vocabulary = set(words)
    size = len(text)
    reachable = [False] * (size + 1)
    reachable[0] = True
    for end in range(1, size + 1):
        for start in range(end):
            if reachable[start] and text[start:end] in vocabulary:
                reachable[end] = True
                break
    return reachable[size]
