def run_length_decode(text):
    out = []
    index = 0
    while index < len(text):
        symbol = text[index]
        if symbol.isdigit():
            raise ValueError("digit where a symbol was expected")
        index += 1
        start = index
        count = 0
        while index < len(text) and text[index].isdigit():
            count = count * 10 + int(text[index])
            index += 1
        if index == start or count == 0:
            raise ValueError("missing or zero count")
        out.append(symbol * count)
