function isValidSudoku(board) {
  if (!Array.isArray(board) || board.length !== 9) throw new RangeError('board must be 9x9');
  for (const row of board) {
    if (!Array.isArray(row) || row.length !== 9) throw new RangeError('board must be 9x9');
  }
  const seen = new Set();
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const value = board[r][c];
      if (value === '.') continue;
      const box = Math.floor(r / 3) * 3 + Math.floor(c / 3);
      const marks = ['r' + r + value, 'c' + c + value, 'b' + box + value];
      for (const mark of marks) {
        if (seen.has(mark)) return false;
        seen.add(mark);
      }
    }
  }
  return true;
}
