function matchesPattern(pattern: string, text: string): boolean {
  let p = 0;
  let t = 0;
  let star = -1;
  let resume = 0;
  while (t < text.length) {
    if (p < pattern.length && (pattern[p] === '?' || pattern[p] === text[t])) {
      p += 1;
      t += 1;
      continue;
    }
    if (p < pattern.length && pattern[p] === '*') {
      star = p;
      resume = t;
      p += 1;
      continue;
    }
    if (star >= 0) {
      p = star + 1;
      resume += 1;
      t = resume;
      continue;
    }
    return false;
  }
  while (p < pattern.length && pattern[p] === '*') p += 1;
  return p === pattern.length;
}
