#include <vector>
#include <stdexcept>

class DisjointSet {
public:
    explicit DisjointSet(int n) : parent(static_cast<std::size_t>(n), 0), weight(static_cast<std::size_t>(n), 1) {
        if (n < 0) throw std::invalid_argument("negative size");
        for (int i = 0; i < n; ++i) parent[static_cast<std::size_t>(i)] = i;
        groups = n;
    }

    int find(int x) {
        check(x);
        int root = x;
        while (parent[static_cast<std::size_t>(root)] != root) root = parent[static_cast<std::size_t>(root)];
        while (parent[static_cast<std::size_t>(x)] != root) {
            int next = parent[static_cast<std::size_t>(x)];
            parent[static_cast<std::size_t>(x)] = root;
            x = next;
        }
        return root;
    }

    bool unite(int a, int b) {
        int left = find(a);
        int right = find(b);
        if (left == right) return false;
        if (weight[static_cast<std::size_t>(left)] < weight[static_cast<std::size_t>(right)]) std::swap(left, right);
        parent[static_cast<std::size_t>(right)] = left;
        weight[static_cast<std::size_t>(left)] += weight[static_cast<std::size_t>(right)];
        --groups;
        return true;
    }

    int components() const { return groups; }

    int size(int x) { return weight[static_cast<std::size_t>(find(x))]; }

private:
    void check(int x) const {
        if (x < 0 || static_cast<std::size_t>(x) >= parent.size()) throw std::out_of_range("bad node");
    }

    std::vector<int> parent;
    std::vector<int> weight;
    int groups = 0;
};
