#include <vector>

long long gcd_int(long long a, long long b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b != 0) {
        long long next = a % b;
        a = b;
        b = next;
    }
    return a;
}

long long lcm_int(long long a, long long b) {
    if (a == 0 || b == 0) return 0;
    long long factor = gcd_int(a, b);
    long long result = (a / factor) * b;
    return result < 0 ? -result : result;
}

std::vector<int> primes_below(int limit) {
    std::vector<int> out;
    if (limit <= 2) return out;
    std::vector<bool> composite(static_cast<std::size_t>(limit), false);
    for (int value = 2; value < limit; ++value) {
        if (composite[static_cast<std::size_t>(value)]) continue;
        out.push_back(value);
        for (long long multiple = static_cast<long long>(value) * value; multiple < limit; multiple += value)
            composite[static_cast<std::size_t>(multiple)] = true;
    }
    return out;
}
