class CircularQueue {
public:
    explicit CircularQueue(int capacity) : buffer(static_cast<std::size_t>(capacity < 1 ? 0 : capacity)), limit(capacity) {
        if (capacity < 1) throw std::invalid_argument("capacity must be positive");
    }

