        if (count == limit) return false;
        buffer[static_cast<std::size_t>((head + count) % limit)] = value;
        ++count;
        return true;
    }

    bool pop() {
        if (count == 0) return false;
        head = (head + 1) % limit;
        --count;
        return true;
    }

    int front() const {
        if (count == 0) throw std::out_of_range("empty queue");
        return buffer[static_cast<std::size_t>(head)];
    }

    int size() const { return count; }
    int capacity() const { return limit; }

private:
    std::vector<int> buffer;
    int limit = 0;
    int head = 0;
    int count = 0;
};
