#include <cassert>
#include <vector>
#include <algorithm>
#include <stdexcept>

std::vector<std::vector<int>> insert_interval(std::vector<std::vector<int>> intervals, std::vector<int> fresh) {
    if (fresh.size() != 2) throw std::invalid_argument("range must have two ends");
    if (fresh[0] > fresh[1]) throw std::invalid_argument("reversed range");
    intervals.push_back(fresh);
    std::vector<std::vector<int>> kept;
    for (const auto& range : intervals) {
        if (range.size() != 2) throw std::invalid_argument("range must have two ends");
        if (range[0] > range[1]) throw std::invalid_argument("reversed range");
        if (range[0] == range[1]) continue;
        kept.push_back(range);
    }
    std::sort(kept.begin(), kept.end(), [](const auto& a, const auto& b) { return a[0] < b[0]; });
    std::vector<std::vector<int>> out;
    for (const auto& range : kept) {
        if (!out.empty() && range[0] <= out.back()[1]) out.back()[1] = std::max(out.back()[1], range[1]);
        else out.push_back({range[0], range[1]});
    }
    return out;
}
