        raise ValueError("out of range")
    if number < 100:
        return _under_hundred(number)
    hundreds, rest = divmod(number, 100)
    base = SMALL[hundreds] + ' hundred'
    if rest == 0:
        return base
    return base + ' and ' + _under_hundred(rest)
