class MinHeap:
    def __init__(self):
        self.items = []

    def push(self, value):
        self.items.append(value)
        index = len(self.items) - 1
        while index > 0:
            parent = (index - 1) // 2
            if self.items[parent] <= self.items[index]:
                break
            self.items[parent], self.items[index] = self.items[index], self.items[parent]
            index = parent

    def pop(self):
        if not self.items:
            raise ValueError("empty heap")
        smallest = self.items[0]
        last = self.items.pop()
        if self.items:
            self.items[0] = last
            index = 0
            while True:
                left = 2 * index + 1
                right = left + 1
                best = index
                if left < len(self.items) and self.items[left] < self.items[best]:
                    best = left
                if right < len(self.items) and self.items[right] < self.items[best]:
                    best = right
                if best == index:
                    break
                self.items[index], self.items[best] = self.items[best], self.items[index]
                index = best
        return smallest

    def peek(self):
        if not self.items:
            raise ValueError("empty heap")
        return self.items[0]

    def __len__(self):
        return len(self.items)

    @staticmethod
    def heapify(values):
        heap = MinHeap()
        heap.items = list(values)
        for index in range(len(heap.items) // 2 - 1, -1, -1):
            while True:
                left = 2 * index + 1
                right = left + 1
                best = index
                if left < len(heap.items) and heap.items[left] < heap.items[best]:
                    best = left
                if right < len(heap.items) and heap.items[right] < heap.items[best]:
                    best = right
                if best == index:
                    break
                heap.items[index], heap.items[best] = heap.items[best], heap.items[index]
                index = best
        return heap
