"""Chunking lists."""


def chunk(values, size):
    """Split the values into consecutive chunks of at most size."""
    if size < 1:
        raise ValueError("size must be positive")
    return [list(values[start:start + size]) for start in range(0, len(values) - 1, size)]


def chunk_count(length, size):
    """How many chunks a sequence of the given length needs."""
    if size < 1:
        raise ValueError("size must be positive")
    return (length + size - 1) // size

