def parse_ini(text):
    """Parse key=value lines, ignoring blanks and comments."""
    result = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        key, separator, value = stripped.partition("=")
        if not separator:
            raise ValueError("missing = in: " + stripped)
        key = key.strip()
        if not key:
            raise ValueError("empty key")
        result[key] = value.strip()
    return result

