function roundTo(value, decimals = 0) {
  if (!Number.isInteger(decimals) || decimals < 0 || decimals > 10) throw new RangeError('bad decimals');
  if (!Number.isFinite(value)) return value;
  const sign = value < 0 ? -1 : 1;
  const scaled = Number(Math.abs(value).toPrecision(15)) * 10 ** decimals;
  const rounded = Math.round(scaled + Number.EPSILON * Math.sign(scaled || 1));
  const result = (sign * rounded) / 10 ** decimals;
  return result === 0 ? 0 : result;
}
