function radixSort(values) {
  const out = [];
  for (const value of values) {
    if (!Number.isInteger(value) || value < 0) throw new RangeError('non-negative integers only');
    out.push(value);
  }
  if (out.length === 0) return out;
  const largest = Math.max(...out);
  for (let place = 1; Math.floor(largest / place) > 0; place *= 10) {
    const buckets = Array.from({ length: 10 }, () => []);
    for (const value of out) buckets[Math.floor(value / place) % 10].push(value);
    out.length = 0;
    for (const bucket of buckets) out.push(...bucket);
  }
  return out;
}
