function shortestCosts(graph, source) {
  if (!graph.has(source)) throw new RangeError('unknown source');
  for (const edges of graph.values()) {
    for (const [, weight] of edges) {
      if (weight < 0) throw new RangeError('negative weight');
    }
  }
  const best = new Map([[source, 0]]);
  const settled = new Set();
  while (true) {
    let current = null;
    let cost = Infinity;
    for (const [node, value] of best) {
      if (settled.has(node)) continue;
      if (value < cost) {
        current = node;
        cost = value;
      }
    }
    if (current === null) break;
    settled.add(current);
    for (const [next, weight] of graph.get(current) ?? []) {
      const candidate = cost + weight;
      if (candidate < (best.get(next) ?? Infinity)) best.set(next, candidate);
    }
  }
  const out = {};
  for (const [node, value] of best) out[node] = value;
  return out;
}
