function parseIPv4(text) {
  if (typeof text !== 'string') throw new RangeError('ipv4 string required');
  const parts = text.split('.');
  if (parts.length !== 4) throw new RangeError('four octets required: ' + text);
  return parts.map(part => {
    if (!/^\d{1,3}$/.test(part)) throw new RangeError('bad octet: ' + part);
    const value = Number(part);
    if (value > 255) throw new RangeError('octet out of range: ' + part);
    return value;
  });
}

function compareIPv4(left, right) {
  const a = parseIPv4(left);
  const b = parseIPv4(right);
  for (let index = 0; index < 4; index++) {
    if (a[index] !== b[index]) return a[index] < b[index] ? -1 : 1;
  }
  return 0;
}
