function binarySearchBy<T>(
  items: readonly T[],
  target: T,
  compare: (a: T, b: T) => number,
): number {
  let low = 0;
  let high = items.length - 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const order = compare(items[mid], target);
    if (order === 0) return mid;
    if (order < 0) low = mid + 1;
    else high = mid - 1;
  }
  return -1;
}
```

