function zipRows(rows: ReadonlyArray<readonly unknown[]>): unknown[][] {
  const width = rows.reduce((widest, row) => Math.max(widest, row.length), 0);
  if (width === 0) return [];
  const out: unknown[][] = [];
  for (let column = 0; column < width; column++) {
    const line: unknown[] = [];
    for (const row of rows) line.push(column < row.length ? row[column] : null);
    out.push(line);
  }
  return out;
}

function unzipRows(rows: ReadonlyArray<readonly unknown[]>): unknown[][] {
  return zipRows(rows);
}
```

