#include <cassert>
#include <vector>
#include <stack>
#include <stdexcept>

int count_components(const std::vector<std::vector<int>>& adjacency) {
    const int size = static_cast<int>(adjacency.size());
    for (const auto& edges : adjacency) {
        for (int next : edges) {
            if (next < 0 || next >= size) throw std::out_of_range("edge outside graph");
        }
    }
    std::vector<bool> seen(adjacency.size(), false);
    int components = 0;
    for (int start = 0; start < size; ++start) {
        if (seen[static_cast<std::size_t>(start)]) continue;
        ++components;
        std::stack<int> pending;
        pending.push(start);
        seen[static_cast<std::size_t>(start)] = true;
        while (!pending.empty()) {
            int node = pending.top();
            pending.pop();
            for (int next : adjacency[static_cast<std::size_t>(node)]) {
                if (seen[static_cast<std::size_t>(next)]) continue;
                seen[static_cast<std::size_t>(next)] = true;
                pending.push(next);
            }
        }
    }
    return components;
}
