#include <cassert>
#include <vector>
#include <stdexcept>
#include <utility>

static int partition_at(std::vector<int>& values, int low, int high) {
    const int mid = low + (high - low) / 2;
    if (values[mid] < values[low]) std::swap(values[mid], values[low]);
    if (values[high] < values[low]) std::swap(values[high], values[low]);
    if (values[high] < values[mid]) std::swap(values[high], values[mid]);
    const int pivot = values[mid];
    std::swap(values[mid], values[high]);
    int store = low;
    for (int i = low; i < high; ++i) {
        if (values[static_cast<std::size_t>(i)] < pivot) {
            std::swap(values[static_cast<std::size_t>(i)], values[static_cast<std::size_t>(store)]);
            ++store;
        }
    }
    std::swap(values[static_cast<std::size_t>(store)], values[static_cast<std::size_t>(high)]);
    return store;
}

int kth_smallest(std::vector<int> values, int k) {
    if (values.empty() || k < 1 || static_cast<std::size_t>(k) > values.size())
        throw std::invalid_argument("bad k");
    int low = 0;
    int high = static_cast<int>(values.size()) - 1;
    const int target = k - 1;
    while (true) {
        if (low == high) return values[static_cast<std::size_t>(low)];
        const int pivot = partition_at(values, low, high);
        if (pivot == target) return values[static_cast<std::size_t>(pivot)];
        if (pivot < target) low = pivot + 1;
        else high = pivot - 1;
    }
}
