#include <cassert>
#include <vector>
#include <stdexcept>

class PrefixSum2D {
public:
    explicit PrefixSum2D(const std::vector<std::vector<int>>& grid) {
        rows = static_cast<int>(grid.size());
        cols = rows == 0 ? 0 : static_cast<int>(grid[0].size());
        for (const auto& row : grid)
            if (static_cast<int>(row.size()) != cols) throw std::invalid_argument("ragged grid");
        table.assign(static_cast<std::size_t>(rows + 1), std::vector<long long>(static_cast<std::size_t>(cols + 1), 0));
        for (int r = 1; r <= rows; ++r) {
            for (int c = 1; c <= cols; ++c) {
                table[static_cast<std::size_t>(r)][static_cast<std::size_t>(c)] =
                    grid[static_cast<std::size_t>(r - 1)][static_cast<std::size_t>(c - 1)]
                    + table[static_cast<std::size_t>(r - 1)][static_cast<std::size_t>(c)]
                    + table[static_cast<std::size_t>(r)][static_cast<std::size_t>(c - 1)]
                    - table[static_cast<std::size_t>(r - 1)][static_cast<std::size_t>(c - 1)];
            }
        }
    }

    long long query(int r1, int c1, int r2, int c2) const {
        if (rows == 0 || cols == 0) {
            if (r1 < 0 || c1 < 0 || r2 < 0 || c2 < 0) throw std::out_of_range("bad rectangle");
            return 0;
        }
        if (r1 > r2 || c1 > c2) throw std::invalid_argument("reversed rectangle");
        if (r1 < 0 || c1 < 0 || r2 >= rows || c2 >= cols) throw std::out_of_range("rectangle outside grid");
        return table[static_cast<std::size_t>(r2 + 1)][static_cast<std::size_t>(c2 + 1)]
             - table[static_cast<std::size_t>(r1)][static_cast<std::size_t>(c2 + 1)]
             - table[static_cast<std::size_t>(r2 + 1)][static_cast<std::size_t>(c1)]
             + table[static_cast<std::size_t>(r1)][static_cast<std::size_t>(c1)];
    }

private:
    int rows = 0;
    int cols = 0;
    std::vector<std::vector<long long>> table;
};
