#include <cassert>
#include <vector>
#include <queue>
#include <stdexcept>

std::vector<int> finish_order(const std::vector<int>& bursts, int quantum) {
    if (quantum < 1) throw std::invalid_argument("quantum must be positive");
    std::queue<int> pending;
    for (std::size_t i = 0; i < bursts.size(); ++i) pending.push(static_cast<int>(i));
    std::vector<int> remaining = bursts;
    std::vector<int> order;
    while (!pending.empty()) {
        const int id = pending.front();
        pending.pop();
        int& left = remaining[static_cast<std::size_t>(id)];
        left -= quantum;
        if (left <= 0) order.push_back(id);
        else pending.push(id);
    }
    return order;
}
