#include <cassert>
#include <vector>
#include <string>
#include <utility>
#include <stdexcept>

static std::string trim(const std::string& text) {
    const auto first = text.find_first_not_of(" \t");
    if (first == std::string::npos) return "";
    const auto last = text.find_last_not_of(" \t");
    return text.substr(first, last - first + 1);
}

std::vector<std::string> parse_pairs(const std::string& text) {
    std::vector<std::string> out;
    std::size_t start = 0;
    while (start <= text.size()) {
        const std::size_t end = text.find(';', start);
        const std::string segment = text.substr(start, end == std::string::npos ? std::string::npos : end - start);
        if (!segment.empty()) {
            const std::size_t split = segment.find('=');
            if (split == std::string::npos) throw std::invalid_argument("missing = in: " + segment);
            out.push_back(trim(segment.substr(0, split)) + ":" + segment.substr(split + 1));
        }
        if (end == std::string::npos) break;
        start = end + 1;
    }
    return out;
}
