#include <cassert>
#include <string>
#include <stdexcept>

std::string pad(const std::string& text, int width, char fill) {
    if (width < 0) throw std::invalid_argument("negative width");
    if (static_cast<int>(text.size()) >= width) return text;
    return text + std::string(static_cast<std::size_t>(width) - text.size(), fill);
}

std::string repeat(const std::string& text, int times) {
    if (times <= 0) return "";
    const std::size_t total = text.size() * static_cast<std::size_t>(times);
    if (total > 1000000u) throw std::length_error("repeated text too long");
    std::string out;
    out.reserve(total);
    for (int i = 0; i < times; ++i) out += text;
    return out;
}
