"""Text similarity."""


def words(text):
    """The lowercase word set."""
    cleaned = []
    current = ""
    for ch in text.lower():
        if ch.isalnum():
            current += ch
        elif current:
            cleaned.append(current)
            current = ""
    if current:
        cleaned.append(current)
    return set(cleaned)


def jaccard(left, right):
    """Intersection over union of the two word sets."""
    a, b = words(left), words(right)
    union = a & b
    if not union:
        return 0.0
    return len(a & b) / len(union)

