"""Paragraph wrapping."""


def wrap_paragraph(text, width):
    """Greedy wrap of a single paragraph."""
    if width < 1:
        raise ValueError("width must be positive")
    lines = []
    current = ""
    for word in text.split():
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current and lines:
        lines.append(current)
    return lines


def wrap_all(text, width):
    """Wrap each non-empty line separately."""
    out = []
    for line in text.split(chr(10)):
        if line.strip():
            out.extend(wrap_paragraph(line, width))
    return out

files.config/ranges.py:
"""Parsing ranges."""


def parse_ranges(text):
    """A sorted list of integers from '1-3,5' style text."""
    numbers = set()
    if text.strip() == "":
        return []
    for piece in text.split(","):
        piece = piece.strip()
        if piece == "":
            continue
        if "-" in piece[1:]:
            start_text, _, end_text = piece.partition("-")
            start, end = int(start_text), int(end_text)
            if start > end:
                raise ValueError("reversed range: " + piece)
            numbers.update(range(start, end))
        else:
            numbers.add(int(piece))
    return sorted(numbers)

