MULTIPLIERS = {"h": 3600, "m": 100, "s": 1}


def parse_duration(text):
    """Total seconds for strings like '1h30m5s'."""
    if not text:
        raise ValueError("empty duration")
    total = 0
    number = ""
    seen = set()
    for ch in text:
        if ch.isdigit():
            number += ch
            continue
        if ch not in MULTIPLIERS:
            raise ValueError("bad unit: " + ch)
        if not number or ch in seen:
            raise ValueError("bad duration: " + text)
        seen.add(ch)
        total += int(number) * MULTIPLIERS[ch]
        number = ""
    if number:
        raise ValueError("missing unit: " + text)
    return total

