"""Card masking."""


def mask_card(number):
    """Mask all but the last four digits, keeping separators."""
    digits = [ch for ch in number if ch.isdigit()]
    if len(digits) < 4:
        return "*" * len(number)
    masked = ["*" for _ in digits[:-4]] + digits[-4:]
    out = []
    index = 0
    for ch in number:
        if ch.isdigit():
            out.append(masked[index])
            index += 1
        else:
            out.append(ch)
    return "".join(out)


def card_last4(number):
    """The last four digits, or None."""
    digits = [ch for ch in number if ch.isdigit()]
    if len(digits) < 4:
        return None
    return "".join(digits[-4:])

