type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

function andThen<T, U, E>(result: Result<T, E>, fn: (value: T) => Result<U, E>): Result<U, E> {
  return result.ok ? fn(result.value) : (result as unknown as Result<U, E>);
}

function mapError<T, E, F>(result: Result<T, E>, fn: (error: E) => F): Result<T, F> {
  return result.ok ? (result as unknown as Result<T, F>) : { ok: false, error: fn(result.error) };
}

function collect<T, E>(results: ReadonlyArray<Result<T, E>>): Result<T[], E> {
  const values: T[] = [];
  for (const result of results) {
    if (!result.ok) return { ok: false, error: result.error };
    values.push(result.value);
  }
  return { ok: true, value: values };
}
