class TypedBus {
  private map = new Map<keyof Events, Array<(payload: never) => void>>();

  on<K extends keyof Events>(name: K, handler: (payload: Events[K]) => void): () => void {
    const bucket = (this.map.get(name) ?? []) as Array<(payload: never) => void>;
    bucket.push(handler as (payload: never) => void);
    this.map.set(name, bucket);
    return () => {
      const current = (this.map.get(name) ?? []) as Array<(payload: never) => void>;
      const index = current.indexOf(handler as (payload: never) => void);
      if (index >= 0) current.splice(index, 1);
      this.map.set(name, current);
    };
  }

  emit<K extends keyof Events>(name: K, payload: Events[K]): number {
    const bucket = (this.map.get(name) ?? []) as Array<(payload: never) => void>;
    for (const handler of [...bucket]) (handler as (payload: Events[K]) => void)(payload);
    return bucket.length;
  }

  count(name: keyof Events): number {
