function maxBy<T>(items: readonly T[], valueOf: (item: T) => number): T | null {
  if (items.length === 0) return null;
  let best = items[0];
  let bestValue = valueOf(best);
  for (let index = 1; index < items.length; index++) {
    const value = valueOf(items[index]);
    if (value > bestValue) {
      best = items[index];
      bestValue = value;
    }
  }
  return best;
}
