#include <vector>

static long long merge_count(std::vector<int>& values, std::vector<int>& buffer, int low, int high) {
    if (high - low < 1) return 0;
    const int middle = (low + high) / 2;
    long long total = merge_count(values, buffer, low, middle) + merge_count(values, buffer, middle + 1, high);
    int left = low;
    int right = middle + 1;
    int write = low;
    while (left <= middle && right <= high) {
        if (values[static_cast<std::size_t>(left)] <= values[static_cast<std::size_t>(right)]) {
            buffer[static_cast<std::size_t>(write++)] = values[static_cast<std::size_t>(left++)];
        } else {
            total += middle - left + 1;
            buffer[static_cast<std::size_t>(write++)] = values[static_cast<std::size_t>(right++)];
        }
    }
    while (left <= middle) buffer[static_cast<std::size_t>(write++)] = values[static_cast<std::size_t>(left++)];
    while (right <= high) buffer[static_cast<std::size_t>(write++)] = values[static_cast<std::size_t>(right++)];
    for (int index = low; index <= high; ++index) values[static_cast<std::size_t>(index)] = buffer[static_cast<std::size_t>(index)];
    return total;
}

long long count_inversions(std::vector<int> values) {
