struct Node {
    int value;
    Node* left;
    Node* right;
    explicit Node(int v, Node* l = nullptr, Node* r = nullptr) : value(v), left(l), right(r) {}
};

int tree_sum(const Node* root) {
    if (root == nullptr) return 0;
    return root->value + tree_sum(root->left) + tree_sum(root->right);
