#include <map>
#include <algorithm>

std::vector<std::string> word_counts(const std::string& text) {
    std::map<std::string, int> counts;
    std::string current;
    auto flush = [&]() {
        if (current.empty()) return;
        std::string lowered;
        for (char ch : current) {
            if (ch >= 'A' && ch <= 'Z') lowered.push_back(static_cast<char>(ch - 'A' + 'a'));
            else lowered.push_back(ch);
        }
        counts[lowered] += 1;
        current.clear();
    };
    for (char ch : text) {
        const bool word_char = (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9');
        if (word_char) current.push_back(ch);
        else flush();
    }
    flush();
    std::vector<std::pair<std::string, int>> ordered(counts.begin(), counts.end());
    std::sort(ordered.begin(), ordered.end(), [](const auto& a, const auto& b) {
        if (a.second != b.second) return a.second > b.second;
        return a.first < b.first;
    });
    std::vector<std::string> out;
    for (const auto& [word, count] : ordered) out.push_back(word + ":" + std::to_string(count));
