#include <cassert>
#include <string>
#include <stdexcept>
#include <limits>

long long parse_integer(const std::string& text) {
    std::size_t start = text.find_first_not_of(" \t");
    if (start == std::string::npos) throw std::invalid_argument("empty number");
    std::size_t end = text.find_last_not_of(" \t");
    const std::string body = text.substr(start, end - start + 1);
    bool negative = false;
    std::size_t index = 0;
    if (body[0] == '+' || body[0] == '-') {
        negative = body[0] == '-';
        index = 1;
    }
    if (index >= body.size()) throw std::invalid_argument("no digits");
    long long value = 0;
    const long long limit = negative ? std::numeric_limits<long long>::min() : std::numeric_limits<long long>::max();
    for (; index < body.size(); ++index) {
        const char ch = body[index];
        if (ch < '0' || ch > '9') throw std::invalid_argument("bad digit: " + std::string(1, ch));
        const int digit = ch - '0';
        if (negative) {
            if (value < (limit + digit) / 10) throw std::out_of_range("too small");
            value = value * 10 - digit;
        } else {
            if (value > (limit - digit) / 10) throw std::out_of_range("too large");
            value = value * 10 + digit;
        }
    }
    return value;
}
