"""Port ranges."""


def parse_ports(text):
    """Expand '80,443,8000-8002' into a sorted list of ports."""
    ports = set()
    for piece in text.split(","):
        piece = piece.strip()
        if not piece:
            continue
        if "-" in piece:
            start_text, _, end_text = piece.partition("-")
            start, end = int(start_text), int(end_text)
            if start > end:
                raise ValueError("reversed range")
            ports.update(range(start, end))
        else:
            ports.add(int(piece))
    for port in ports:
        if not 1 <= port <= 65535:
            raise ValueError("port out of range")
    return sorted(ports)


def port_count(text):
    """How many distinct ports the text describes."""
    return len(parse_ports(text))

