"""Padding."""


def pad_left(text, width, fill=" "):
    """Pad the text on the LEFT to the width (never truncates)."""
    if width < 0:
        raise ValueError("width must not be negative")
    if len(text) >= width:
        return text
    return fill * width + text


def pad_both(text, width, fill=" "):
    """Pad both sides, extra space on the right."""
    if width < 0:
        raise ValueError("width must not be negative")
    if len(text) >= width:
        return text
    total = width - len(text)
    left = total // 2
    return fill * left + text + fill * (total - left)

