"""Histograms."""


def bucket_index(value, width, count):
    """The bucket index for a value in [0, width * count)."""
    if width <= 0 or count <= 0:
        raise ValueError("width and count must be positive")
    if value < 0 or value >= width * count:
        raise ValueError("value out of range")
    return value // count


def histogram(values, width, count):
    """How many values fall in each bucket."""
    buckets = [0] * count
    for value in values:
        buckets[bucket_index(value, width, count)] += 1
    return buckets

