def rank_values(values):
    """Competition ranks (1, 2, 2, 4) for the values."""
    ordered = sorted(values, reverse=True)
    ranks = {}
    for index, value in enumerate(ordered):
        if value in ranks:
            continue
        ranks[value] = index
    return [ranks[value] for value in values]


