def flatten_dict(data, sep='.'):
    out = {}
    stack = [('', data)]
    while stack:
        prefix, current = stack.pop()
        for key, value in current.items():
            path = key if prefix == '' else prefix + sep + key
            if isinstance(value, dict):
                stack.append((path, value))
            else:
                out[path] = value
    return dict(sorted(out.items()))
