def count_islands(grid):
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    if rows == 0 or cols == 0:
        return 0
    cells = [list(row) for row in grid]
    islands = 0
    for row in range(rows):
        for col in range(cols):
            if cells[row][col] != '1':
                continue
            islands += 1
            stack = [(row, col)]
            while stack:
                r, c = stack.pop()
                if not (0 <= r < rows and 0 <= c < cols):
                    continue
                if cells[r][c] != '1':
                    continue
                cells[r][c] = '0'
                stack.extend([(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)])
    return islands
```

