function parseQuery(input: string): Record<string, string> {
  const out: Record<string, string> = {};
  const mark = input.indexOf('?');
  const query = mark === -1 ? input : input.slice(mark + 1);
  for (const part of query.split('&')) {
    if (part === '') continue;
    const eq = part.indexOf('=');
    const key = decodeURIComponent(eq === -1 ? part : part.slice(0, eq));
    const value = eq === -1 ? '' : decodeURIComponent(part.slice(eq + 1));
    if (!Object.prototype.hasOwnProperty.call(out, key)) out[key] = value;
  }
  return out;
}
