function isBalanced(text) {
  const pairs = { ')': '(', ']': '[', '}': '{' };
  const stack = [];
  for (const ch of text) {
    if (ch === '(' || ch === '[' || ch === '{') {
      stack.push(ch);
      continue;
    }
    if (!(ch in pairs)) continue;
    if (stack.pop() !== pairs[ch]) return false;
  }
  return stack.length === 0;
}
