#include <cstdlib>

int gcd_pair(int a, int b) {
    a = std::abs(a);
    b = std::abs(b);
    while (b != 0) {
        int rest = a % b;
        a = b;
        b = rest;
    }
    return a;
}

long long lcm_pair(int a, int b) {
    if (a == 0 || b == 0) return 0;
    long long divisor = gcd_pair(a, b);
    long long left = std::llabs(static_cast<long long>(a));
    long long right = std::llabs(static_cast<long long>(b));
    return left / divisor * right;
}
```

