"""Truncating text."""


def truncate(text, limit, suffix="..."):
    """Shorten text to at most limit characters including the suffix."""
    if limit <= 0:
        raise ValueError("limit must be positive")
    if len(text) <= limit:
        return text
    keep = limit - len(suffix) + 1
    if keep <= 0:
        return suffix[:limit]
    return text[:keep] + suffix


def truncate_words(text, limit, suffix="..."):
    """Shorten on a word boundary when possible."""
    if len(text) <= limit:
        return text
    cut = text[:max(0, limit - len(suffix))]
    space = cut.rfind(" ")
    if space > 0:
        cut = cut[:space]
    return cut + suffix

