"""Percentiles."""


def percentile(values, fraction):
    """The value at the given fraction (0..1) using nearest rank."""
    if not values:
        raise ValueError("empty values")
    if not 0 <= fraction <= 1:
        raise ValueError("fraction out of range")
    ordered = sorted(values)
    index = int(round(fraction * len(ordered)))
    return ordered[index]


def median(values):
    """The middle value (mean of the two middle ones for even sizes)."""
    if not values:
        raise ValueError("empty values")
    ordered = sorted(values)
    middle = len(ordered) // 2
    if len(ordered) % 2:
        return ordered[middle]
    return (ordered[middle - 1] + ordered[middle]) / 2

files.graph/shortest_path.py:
"""Shortest paths."""


def shortest_path(graph, start, goal):
    """The number of edges on the shortest path, or None."""
    if start == goal:
        return 0
    seen = {start}
    queue = [(start, 0)]
    head = 0
    while head < len(queue):
        node, distance = queue[head]
        head += 1
        for neighbour in graph.get(node, ()):
            if neighbour in seen:
                continue
            if neighbour == goal:
                return distance
            seen.add(neighbour)
            queue.append((neighbour, distance + 1))
    return None

