```python
def has_cycle(graph):
    state = {}

    def visit(node):
        colour = state.get(node, 0)
        if colour == 1:
            return True
        if colour == 2:
            return False
        state[node] = 1
        for neighbour in graph.get(node, ()):
            if visit(neighbour):
                return True
        state[node] = 2
        return False

    return any(visit(node) for node in list(graph))


def topo_order(graph):
    """A topological order, or None when a cycle exists."""
    if has_cycle(graph):
        return None
    output = []
    seen = set()

    def walk(node):
        if node in seen:
            return
        seen.add(node)
        for neighbour in graph.get(node, ()):
            walk(neighbour)
        output.append(node)

    for node in graph:
        walk(node)
    return output[::-1]
```

