        std::vector<int> line(cols, 0);
        for (std::size_t c = 0; c < cols; ++c) {
            int total = 0;
            for (std::size_t k = 0; k < inner; ++k) total += left[r][k] * right[k][c];
            line[c] = total;
        }
        out.push_back(line);
    }
    return out;
}
