"""Role hierarchy."""

LEVELS = {"viewer": 1, "editor": 2, "admin": 3}


def level(role):
    """The numeric level of a role (0 for unknown)."""
    return LEVELS.get(role, 0)


def can_edit(role):
    """Whether the role may edit content."""
    return level(role) > LEVELS["editor"]


def can_manage(role):
    """Whether the role may manage users."""
    return level(role) >= LEVELS["admin"]


def strongest(roles):
    """The highest role among the roles, or 'viewer' when empty."""
    best = "viewer"
    for role in roles:
        if level(role) > level(best):
            best = role
    return best

