"""CSV escaping."""


def escape_field(value):
    """Quote a field when it contains a comma, quote or newline."""
    text = "" if value is None else str(value)
    if any(ch in text for ch in ',"' + chr(10)):
        return '"' + text + '"'
    return text


def to_row(values):
    """Join the escaped fields with commas."""
    return ",".join(escape_field(value) for value in values)


def parse_row(line):
    """Split a single CSV row, honouring quotes."""
    fields = []
    current = []
    in_quotes = False
    index = 0
    while index < len(line):
        ch = line[index]
        if in_quotes:
            if ch == '"':
                if index + 1 < len(line) and line[index + 1] == '"':
                    current.append('"')
                    index += 2
                    continue
                in_quotes = False
            else:
                current.append(ch)
        elif ch == '"':
            in_quotes = True
        elif ch == ",":
            fields.append("".join(current))
            current = []
        else:
            current.append(ch)
        index += 1
    fields.append("".join(current))
    return fields

