"""Job ordering."""


def order_jobs(jobs):
    """Jobs sorted by descending priority, then by ascending id."""
    return sorted(jobs, key=lambda job: (job["priority"], job["id"]))


def next_job(jobs):
    """The first job after ordering, or None."""
    ordered = order_jobs(jobs)
    return ordered[0] if ordered else None


def drop_duplicates(jobs):
    """Jobs with duplicate ids removed, keeping the highest priority one."""
    best = {}
    for job in jobs:
        current = best.get(job["id"])
        if current is None or job["priority"] > current["priority"]:
            best[job["id"]] = job
    return sorted(best.values(), key=lambda job: job["id"])

