function parseHex(text) {
  const body = text.toLowerCase().startsWith('0x') ? text.slice(2) : text;
  if (body.length === 0) throw new Error('empty hex string');
  let total = 0;
  for (const ch of body.toLowerCase()) {
    const code = ch.charCodeAt(0);
    let digit;
    if (code >= 48 && code <= 57) digit = code - 48;
    else if (code >= 97 && code <= 102) digit = code - 87;
    else throw new Error('bad hex digit: ' + ch);
    total = total * 16 + digit;
  }
  return total;
}
```

