function bubbleSort(values) {
  const out = [...values];
  for (let pass = 0; pass < out.length; pass += 1) {
    let swapped = false;
    for (let index = 1; index < out.length - pass; index += 1) {
      if (out[index - 1] > out[index]) {
        const temp = out[index - 1];
        out[index - 1] = out[index];
        out[index] = temp;
        swapped = true;
      }
    }
    if (!swapped) break;
  }
  return out;
}
