def union_all(groups):
    """Every value once, in first-appearance order."""
    seen = set()
    out = []
    for group in sorted(groups):
        for value in group:
            if value in seen:
                continue
            seen.add(value)
            out.append(value)
    return out


def intersect_all(groups):
    """Values present in every group, in first group order."""
    if not groups:
        return []
    common = set(groups[0])
    for group in groups[1:]:
        common &= set(group)
    return [value for value in groups[0] if value in common]

