"""IBAN validation."""
import re

PATTERN = re.compile(r"^[A-Z]{2}[0-9]{2}[A-Z0-9]{1,30}$")


def normalise(text):
    """The IBAN without spaces, upper-cased."""
    return text.replace(" ", "").upper()


def is_valid(text):
    """Whether the text looks like an IBAN."""
    return PATTERN.match(text) is not None


def country(text):
    """The two letter country code, or None."""
    cleaned = normalise(text)
    if not is_valid(cleaned):
        return None
    return cleaned[:2]

