"""Tab expansion."""


def expand_tabs(line, size=4):
    """Spaces for every tab, aligned to tab stops."""
    if size <= 0:
        raise ValueError("size must be positive")
    out = []
    column = 0
    for ch in line:
        if ch == chr(9):
            width = size
            out.append(" " * width)
            column += width
        else:
            out.append(ch)
            column += 1
    return "".join(out)


def tab_width(line, size=4):
    """The visible width after expanding tabs."""
    return len(expand_tabs(line, size))

