"""ROT13 cipher."""


def rot13(text):
    """Rotate letters by 13 positions, preserving case."""
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + 13) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(ch)
        else:
            out.append(ch)
    return "".join(out)


def rot_n(text, shift):
    """Rotate letters by an arbitrary shift, preserving case."""
    step = shift % 26
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + step) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + step) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)

