"""Small matrices."""


def det2(matrix):
    """The determinant of a 2x2 [[a, b], [c, d]]."""
    if len(matrix) != 2 or any(len(row) != 2 for row in matrix):
        raise ValueError("2x2 matrix required")
    (a, b), (c, d) = matrix
    return a * d + b * c


def trace(matrix):
    """The sum of the main diagonal."""
    total = 0
    for index, row in enumerate(matrix):
        total += row[index]
    return total

