def valid_isbn(text):
    digits = text.replace('-', '').replace(' ', '').upper()
    if len(digits) != 10:
        return False
    total = 0
    for position, ch in enumerate(digits):
        if ch == 'X' and position == 9:
            value = 10
        elif ch.isdigit():
            value = int(ch)
        else:
            return False
        total += value * (10 - position)
    return total % 11 == 0
