def first_fit(items, capacity):
    if capacity <= 0:
        raise ValueError("capacity must be positive")
    rooms = []
    for item in items:
        if item > capacity:
            raise ValueError("item does not fit")
        for index, room in enumerate(rooms):
            if room >= item:
                rooms[index] = room - item
                break
        else:
            rooms.append(capacity - item)
    return rooms
