"""Atbash cipher."""


def atbash(text):
    """Map a<->z, b<->y, ... preserving case."""
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr(ord("z") - (ord(ch) - ord("a"))))
        elif "A" <= ch <= "Z":
            out.append(ch)
        else:
            out.append(ch)
    return "".join(out)


def is_atbash_pair(left, right):
    """Whether right is the Atbash form of left."""
    return atbash(left) == right

