```python
def min_path_sum(grid):
    if not grid or not grid[0]:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    best = [[0] * cols for _ in range(rows)]
    for row in range(rows):
        for col in range(cols):
            if row == 0 and col == 0:
                best[row][col] = grid[row][col]
            elif row == 0:
                best[row][col] = best[row][col - 1] + grid[row][col]
            elif col == 0:
                best[row][col] = best[row - 1][col] + grid[row][col]
            else:
                best[row][col] = min(best[row - 1][col], best[row][col - 1]) + grid[row][col]
    return best[rows - 1][cols - 1]
```

