"""Card numbers."""


def luhn_total(digits):
    """The Luhn checksum of the digit string."""
    total = 0
    double = True
    for ch in reversed(digits):
        if not ch.isdigit():
            raise ValueError("digits only")
        value = int(ch)
        if double:
            value *= 2
            if value > 9:
                value -= 9
        total += value
        double = not double
    return total


def valid_card(text):
    """Whether the number passes the Luhn check."""
    digits = text.replace(" ", "").replace("-", "")
    if not digits.isdigit() or not 12 <= len(digits) <= 19:
        return False
    return luhn_total(digits) % 10 == 0

