"""Log lines."""


def parse_line(line):
    """Split 'LEVEL message with: colons' into (level, message)."""
    level, sep, message = line.partition(":")
    if not sep:
        raise ValueError("no message")
    return (level, message)


def count_levels(lines):
    """How many lines each level has."""
    counts = {}
    for line in lines:
        level, _ = parse_line(line)
        counts[level] = counts.get(level, 0) + 1
    return counts

