class Grid {
  rows: number;
  cols: number;
  cells: number[][];

  constructor(rows: number, cols: number) {
    this.rows = rows;
    this.cols = cols;
    this.cells = [];
    for (let row = 0; row < rows; row += 1) this.cells.push(new Array(cols).fill(0));
  }

  get(row: number, col: number): number | undefined {
    if (row < 0 || col < 0 || row >= this.rows || col >= this.cols) return undefined;
    return this.cells[row][col];
  }

  set(row: number, col: number, value: number): void {
    if (row < 0 || col < 0 || row >= this.rows || col >= this.cols) throw new Error('out of bounds');
    this.cells[row][col] = value;
  }

  neighbours(row: number, col: number): number[][] {
    const out: number[][] = [];
    for (const [dr, dc] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
      const r = row + dr;
      const c = col + dc;
      if (r >= 0 && c >= 0 && r < this.rows && c < this.cols) out.push([r, c]);
    }
    return out;
  }
}
```

