def to_24h(text):
    parts = text.strip().upper().split()
    if len(parts) != 2 or parts[1] not in ('AM', 'PM'):
        raise ValueError("bad time: " + text)
    clock = parts[0].split(':')
    if len(clock) != 2 or not clock[0].isdigit() or not clock[1].isdigit():
        raise ValueError("bad time: " + text)
    hours = int(clock[0])
    minutes = int(clock[1])
    if not 1 <= hours <= 12 or not 0 <= minutes <= 59:
        raise ValueError("bad time: " + text)
    if parts[1] == 'AM':
        hours = 0 if hours == 12 else hours
    else:
        hours = 12 if hours == 12 else hours + 12
    return '{:02d}:{:02d}'.format(hours, minutes)
