"""Parsing numbers."""


def to_int(text):
    """Parse an integer with an optional leading sign."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("empty text")
    sign = 1
    if cleaned[0] in "+-":
        sign = 1
        cleaned = cleaned[1:]
    if not cleaned or not cleaned.isdigit():
        raise ValueError("bad number: " + text)
    return sign * int(cleaned)


def clamp_int(text, low, high):
    """Parse an integer and clamp it into the range."""
    value = to_int(text)
    if value < low:
        return low
    if value > high:
        return high
    return value

