"""Centring."""


def centre(text, width, fill=" "):
    """Centre the text in the width, extra padding on the right."""
    if width < 0:
        raise ValueError("width must not be negative")
    if len(text) >= width:
        return text
    total = width - len(text)
    left = total
    return fill * left + text + fill * (total - left)


def left_pad(text, width, fill="0"):
    """Pad numbers on the left."""
    if width < 0:
        raise ValueError("width must not be negative")
    if len(text) >= width:
        return text
    return fill * (width - len(text)) + text

