function duplicates<T>(values: T[]): T[] {
  const seen = new Set<T>();
  const reported = new Set<T>();
  const out: T[] = [];
  for (const value of values) {
    if (seen.has(value)) {
      if (!reported.has(value)) {
        reported.add(value);
        out.push(value);
      }
      continue;
    }
    seen.add(value);
  }
  return out;
}
