def sieve(limit):
    if limit <= 2:
        return []
    flags = [True] * limit
    flags[0] = False
    flags[1] = False
    for candidate in range(2, int(limit ** 0.5) + 1):
        if not flags[candidate]:
            continue
        for multiple in range(candidate * candidate, limit, candidate):
            flags[multiple] = False
    return [value for value in range(limit) if flags[value]]
```

