"""Integer parsing."""


def int_part(text):
    """The integer part of a numeric string."""
    cleaned = text.strip()
    if not cleaned:
        raise ValueError("empty text")
    sign = -1 if cleaned.startswith("-") else 1
    body = cleaned[1:] if cleaned[:1] in "+-" else cleaned
    whole = body.split(" ")[0]
    if not whole.isdigit():
        raise ValueError("bad number: " + text)
    return sign * int(whole)

