"""Bubble sort."""


def bubble(values):
    """Sort the values ascending with bubble sort, returning a new list."""
    out = list(values)
    for _ in range(len(out)):
        swapped = False
        for index in range(1, len(out)):
            if out[index - 1] < out[index]:
                out[index - 1], out[index] = out[index], out[index - 1]
                swapped = True
        if not swapped:
            break
    return out

