"""ISO dates."""


def valid_date(text):
    """Whether the text is a YYYY-MM-DD date with a 1..12 month and 1..31 day."""
    parts = text.split("-")
    if len(parts) != 3:
        return False
    year, month, day = parts
    if len(year) != 4 or not year.isdigit():
        return False
    if not month.isdigit() or not day.isdigit():
        return False
    if len(month) != 2 or len(day) != 2:
        return False
    return 0 <= int(month) <= 12 and 1 <= int(day) <= 31


def year_of(text):
    """The year of a valid date, or None."""
    if not valid_date(text):
        return None
    return int(text.split("-")[0])

