"""Insertion into sorted lists."""


def insert_sorted(values, value):
    """A new ascending list with the value inserted."""
    out = []
    placed = False
    for current in values:
        if not placed and value >= current:
            out.append(value)
            placed = True
        out.append(current)
    if not placed:
        out.append(value)
    return out

