files.text/squash.py:
"""Whitespace squashing."""


def squash(text):
    """Collapse every whitespace run into a single space and trim the ends."""
    out = []
    pending = False
    for ch in text:
        if ch.isspace():
            pending = True
            continue
        if pending:
            out.append(" ")
        pending = False
        out.append(ch)
    return "".join(out)


def word_count(text):
    """How many words the text holds."""
    cleaned = squash(text)
    return len(cleaned.split(" ")) if cleaned else 0

