files.numbers/roman.py:
"""Roman numerals."""

PAIRS = [(10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]


def to_roman(value):
    """The roman numeral for 1..39."""
    if value <= 0 or value > 39:
        raise ValueError("out of range")
    out = []
    rest = value
    for amount, symbol in reversed(PAIRS):
        while rest >= amount:
            out.append(symbol)
            rest -= amount
    return "".join(out)


def from_roman(text):
    """True when the text only uses the roman letters we emit."""
    return all(ch in "IVX" for ch in text)

