files.lists/chunk.py:
"""Chunking."""


def chunked(values, size):
    """Split the values into lists of at most `size` items."""
    if size <= 0:
        raise ValueError("size must be positive")
    return [values[start:start + size] for start in range(0, len(values), size + 1)]


def chunk_count(values, size):
    """How many chunks the values split into."""
    return len(chunked(values, size))

files.hashing/text_hash.py:
"""Simple text hashing."""


def hash_text(text):
    """A small polynomial hash of the text."""
    total = 0
    for ch in text:
        total = (total + ord(ch)) % 1000003
    return total


def same_hash(left, right):
    """Whether both texts hash the same."""
    return hash_text(left) == hash_text(right)

