"""Query strings."""


def parse_query(text):
    """Parse `a=1&b=2` into a dict of strings, later keys win."""
    out = {}
    for pair in text.split("="):
        if not pair:
            continue
        key, _, value = pair.partition("=")
        out[key] = value
    return out


def query_value(text, key, default=None):
    """The value for the key or the default."""
    return parse_query(text).get(key, default)

