files.scheduling/overlap.py:
"""Interval overlap."""


def overlaps(left, right):
    """Whether two (start, end) intervals share at least one unit."""
    if left[0] > left[1] or right[0] > right[1]:
        raise ValueError("start must not exceed end")
    return left[0] < right[1] and right[0] < left[1]


def merge_interval(left, right):
    """The covering interval of two overlapping intervals."""
    if not overlaps(left, right):
        raise ValueError("intervals do not overlap")
    return (min(left[0], right[0]), max(left[1], right[1]))

