"""Caesar shifts."""


def shift(text, amount):
    """Shift the letters of the text, wrapping within the same case."""
    step = amount % 26
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr(ord(ch) - 97 + step + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + step) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)


def unshift(text, amount):
    """Undo a shift."""
    return shift(text, -amount)
